local __modules = {}
local __cache = {}
local __loading = {}

local function __require(name)
    local cached = __cache[name]
    if cached ~= nil then
        return cached
    end
    if __loading[name] then
        error("Circular module dependency: " .. tostring(name), 0)
    end
    local factory = __modules[name]
    if type(factory) ~= "function" then
        error("Unknown bundled module: " .. tostring(name), 0)
    end
    __loading[name] = true
    local ok, result = pcall(factory)
    __loading[name] = nil
    if not ok then
        error("Bundled module failed (" .. tostring(name) .. "): " .. tostring(result), 0)
    end
    __cache[name] = result
    return result
end

__modules["Shared.AuthorizationPolicy"] = function()
--!nonstrict
-- Pure authorization policy. The server evaluates this table; the client never
-- supplies its own place ID, user ID, or allowlist. Local Studio playtests are
-- explicitly enabled by the server config and are still server-authoritative.

local AuthorizationPolicy = {}

export type Request = {
    placeId: number?,
    userId: number?,
    isStudio: boolean?,
    allowStudio: boolean?,
    authorizedPlaceIds: { number }?,
    authorizedUserIds: { number }?,
}

export type Decision = {
    authorized: boolean,
    code: string,
    scope: string,
}

local function containsNumber(values: { number }?, needle: number?): boolean
    if not values or needle == nil then
        return false
    end
    for _, value in ipairs(values) do
        if value == needle then
            return true
        end
    end
    return false
end

function AuthorizationPolicy.evaluate(request: Request): Decision
    local placeId = request.placeId
    local userId = request.userId
    local isStudio = request.isStudio == true
    local allowStudio = request.allowStudio == true
    local places = request.authorizedPlaceIds or {}
    local users = request.authorizedUserIds or {}

    local placeAuthorized = (isStudio and allowStudio)
        or (placeId ~= nil and containsNumber(places, placeId))

    if not placeAuthorized then
        return {
            authorized = false,
            code = "PLACE_NOT_AUTHORIZED",
            scope = "none",
        }
    end

    -- In Studio, the local player is the developer running the test. Published
    -- places require an explicit tester allowlist even when the place itself
    -- is allowlisted, so enabling the server component cannot silently expose
    -- development tools to every player in a public test place.
    if isStudio and allowStudio then
        return {
            authorized = true,
            code = "OK",
            scope = "studio",
        }
    end

    if #users == 0 then
        return {
            authorized = false,
            code = "TESTER_ALLOWLIST_EMPTY",
            scope = "place",
        }
    end

    if not containsNumber(users, userId) then
        return {
            authorized = false,
            code = "TESTER_NOT_AUTHORIZED",
            scope = "place",
        }
    end

    return {
        authorized = true,
        code = "OK",
        scope = "place",
    }
end

function AuthorizationPolicy.isPlaceAuthorized(placeId: number?, isStudio: boolean?, allowStudio: boolean?, authorizedPlaceIds: { number }?): boolean
    if isStudio and allowStudio then
        return true
    end
    return placeId ~= nil and containsNumber(authorizedPlaceIds, placeId)
end

return AuthorizationPolicy
end

__modules["Shared.CleanupManager"] = function()
--!nonstrict
-- One cleanup scope per session or module. It owns the "stop twice" problem:
-- cleanup is idempotent, and anything registered after cleanup is cleaned up
-- immediately instead of leaking into a dead module.

local CleanupManager = {}
CleanupManager.__index = CleanupManager

function CleanupManager.new(name: string?)
    local self = setmetatable({}, CleanupManager)
    self.name = name or "cleanup"
    self._connections = {}
    self._instances = {}
    self._functions = {}
    self._cleaned = false
    return self
end

local function safeDisconnect(connection: any)
    if type(connection) == "table" or type(connection) == "userdata" then
        local ok = pcall(function()
            connection:Disconnect()
        end)
        return ok
    end
    return false
end

local function safeDestroy(instance: any)
    if instance == nil then
        return false
    end
    return pcall(function()
        instance:Destroy()
    end)
end

function CleanupManager:addConnection(connection: any): any
    if connection == nil then
        return nil
    end
    if self._cleaned then
        safeDisconnect(connection)
        return connection
    end
    table.insert(self._connections, connection)
    return connection
end

function CleanupManager:addInstance(instance: any): any
    if instance == nil then
        return nil
    end
    if self._cleaned then
        safeDestroy(instance)
        return instance
    end
    table.insert(self._instances, instance)
    return instance
end

function CleanupManager:addFunction(callback: () -> ()): () -> ()
    if type(callback) ~= "function" then
        return callback
    end
    if self._cleaned then
        pcall(callback)
        return callback
    end
    table.insert(self._functions, callback)
    return callback
end

function CleanupManager:cleanup()
    if self._cleaned then
        return
    end
    self._cleaned = true

    for _, connection in ipairs(self._connections) do
        safeDisconnect(connection)
    end
    self._connections = {}

    for _, instance in ipairs(self._instances) do
        safeDestroy(instance)
    end
    self._instances = {}

    for _, callback in ipairs(self._functions) do
        pcall(callback)
    end
    self._functions = {}
end

function CleanupManager:isCleaned(): boolean
    return self._cleaned
end

function CleanupManager:count(): number
    return #self._connections + #self._instances + #self._functions
end

return CleanupManager
end

__modules["Shared.ConfigDefaults"] = function()
--!nonstrict
-- Schema-driven client configuration. Feature activation is intentionally NOT
-- part of this table: no stored value can start a module before the server
-- environment and its dependencies are ready.

local Validation = __require("Shared.Validation")

local ConfigDefaults = {}

local STYLES = { "Billboard", "Billboard + Highlight" }
local THEMES = { "Agamtrash Charcoal", "DarkBlue", "Default" }
local ATM_MODES = { "validate", "mock" }

-- Paths are dotted; values are plain Lua data so the schema can be unit tested
-- without Roblox types.
ConfigDefaults.schema = {
    { path = "Settings.DebugLogging", kind = "boolean", default = false },
    { path = "Settings.Theme", kind = "enum", default = "Agamtrash Charcoal", options = THEMES },

    { path = "Money.Radius", kind = "number", default = 10000, min = 100, max = 10000 },
    { path = "Money.Interval", kind = "number", default = 1.0, min = 0.25, max = 5.0 },
    { path = "Money.Debug", kind = "boolean", default = false },

    { path = "Combat.Range", kind = "number", default = 25, min = 5, max = 100 },
    { path = "Combat.Interval", kind = "number", default = 1.0, min = 0.5, max = 5.0 },
    { path = "Combat.VisualRange", kind = "number", default = 200, min = 10, max = 500 },
    { path = "Combat.Style", kind = "enum", default = "Billboard", options = STYLES },
    { path = "Combat.ShowName", kind = "boolean", default = true },
    { path = "Combat.ShowDistance", kind = "boolean", default = true },
    { path = "Combat.ShowHealth", kind = "boolean", default = false },

    { path = "Items.VisualRange", kind = "number", default = 300, min = 50, max = 1000 },
    { path = "Items.Style", kind = "enum", default = "Billboard", options = STYLES },
    { path = "Items.ShowName", kind = "boolean", default = true },
    { path = "Items.ShowDistance", kind = "boolean", default = true },

    { path = "ATM.Interval", kind = "number", default = 3.0, min = 0.5, max = 10.0 },
    { path = "ATM.Mode", kind = "enum", default = "validate", options = ATM_MODES },
    { path = "ATM.Debug", kind = "boolean", default = false },
}

local function deepCopy(value: any): any
    if type(value) ~= "table" then
        return value
    end
    local copy = {}
    for key, child in pairs(value) do
        copy[key] = deepCopy(child)
    end
    return copy
end

local function splitPath(path: string): { string }
    local parts = {}
    for part in string.gmatch(path, "[^%.]+") do
        table.insert(parts, part)
    end
    return parts
end

local function setPath(target: table, path: string, value: any)
    local parts = splitPath(path)
    local cursor = target
    for index = 1, #parts - 1 do
        local key = parts[index]
        if type(cursor[key]) ~= "table" then
            cursor[key] = {}
        end
        cursor = cursor[key]
    end
    cursor[parts[#parts]] = value
end

local function getPath(target: table, path: string): any
    local cursor = target
    for part in string.gmatch(path, "[^%.]+") do
        if type(cursor) ~= "table" then
            return nil
        end
        cursor = cursor[part]
    end
    return cursor
end

ConfigDefaults.getPath = getPath
ConfigDefaults.setPath = setPath

local function buildDefaults(): table
    local config = {}
    for _, entry in ipairs(ConfigDefaults.schema) do
        setPath(config, entry.path, deepCopy(entry.default))
    end
    return config
end

ConfigDefaults.defaults = buildDefaults()

local function findSchema(path: string): table?
    for _, entry in ipairs(ConfigDefaults.schema) do
        if entry.path == path then
            return entry
        end
    end
    return nil
end

ConfigDefaults.findSchema = findSchema

-- Normalizes an untrusted table (for example a future import feature). Type
-- errors use safe defaults; out-of-range finite numbers are clamped. Every
-- adjustment is reported rather than hidden.
function ConfigDefaults.normalize(raw: any): (table, { string })
    local issues = {}
    local result = {}
    if type(raw) ~= "table" then
        if raw ~= nil then
            table.insert(issues, "Configuration root was not a table; defaults applied.")
        end
        raw = {}
    end

    for _, entry in ipairs(ConfigDefaults.schema) do
        local supplied = getPath(raw, entry.path)
        local value = entry.default

        if entry.kind == "boolean" then
            if supplied == nil then
                value = entry.default
            elseif type(supplied) == "boolean" then
                value = supplied
            else
                table.insert(issues, entry.path .. " must be a boolean; default applied.")
            end
        elseif entry.kind == "number" then
            if supplied == nil then
                value = entry.default
            else
                local normalized, adjusted = Validation.number(supplied, entry.default, entry.min, entry.max)
                value = normalized
                if adjusted then
                    table.insert(issues, entry.path .. " was clamped to its allowed range.")
                elseif normalized ~= supplied then
                    table.insert(issues, entry.path .. " was not a finite number; default applied.")
                end
            end
        elseif entry.kind == "enum" then
            if supplied == nil then
                value = entry.default
            elseif Validation.hasOption(entry.options, supplied) then
                value = supplied
            else
                table.insert(issues, entry.path .. " is not a supported option; default applied.")
            end
        end

        -- Only schema paths are copied. Unknown keys never enter the runtime.
        setPath(result, entry.path, value)
    end

    return result, issues
end

function ConfigDefaults.validateValue(path: string, value: any): (boolean, any, string?)
    local entry = findSchema(path)
    if not entry then
        return false, nil, "Unknown configuration path."
    end

    if entry.kind == "boolean" then
        if type(value) ~= "boolean" then
            return false, nil, "Expected a boolean."
        end
        return true, value, nil
    end

    if entry.kind == "number" then
        if not Validation.isFiniteNumber(value) then
            return false, nil, "Expected a finite number."
        end
        if value < entry.min or value > entry.max then
            return false, nil, string.format("Expected a number between %s and %s.", tostring(entry.min), tostring(entry.max))
        end
        return true, value, nil
    end

    if entry.kind == "enum" then
        if not Validation.hasOption(entry.options, value) then
            return false, nil, "Expected one of the supported options."
        end
        return true, value, nil
    end

    return false, nil, "Unsupported schema kind."
end

function ConfigDefaults.copy(value: any): any
    return deepCopy(value)
end

return ConfigDefaults
end

__modules["Shared.ConfigManager"] = function()
--!nonstrict
-- Holds the validated, in-memory client configuration. There is deliberately
-- no automatic loading from a file: persisted values must never start modules
-- or reconnect gameplay features before the environment is ready.

local ConfigDefaults = __require("Shared.ConfigDefaults")
local Validation = __require("Shared.Validation")

local ConfigManager = {}
ConfigManager.__index = ConfigManager

function ConfigManager.new(logger: any?)
    local self = setmetatable({}, ConfigManager)
    self._logger = logger
    self._values = ConfigDefaults.normalize({})
    self._listeners = {}
    return self
end

function ConfigManager:get(): table
    -- Modules read this table; they must treat it as read-only. Mutation goes
    -- through :set so every value is validated.
    return self._values
end

function ConfigManager:getValue(path: string): any
    return ConfigDefaults.getPath(self._values, path)
end

function ConfigManager:set(path: string, value: any): (boolean, string?)
    local ok, normalized, reason = ConfigDefaults.validateValue(path, value)
    if not ok then
        if self._logger then
            self._logger:warn("Configuration rejected: " .. path .. " - " .. tostring(reason))
        end
        return false, reason
    end

    local current = self:getValue(path)
    if current == normalized then
        return true, nil
    end

    ConfigDefaults.setPath(self._values, path, normalized)
    for _, listener in ipairs(self._listeners) do
        local success, err = pcall(listener, path, normalized)
        if not success and self._logger then
            self._logger:warn("Configuration listener failed: " .. Validation.truncate(err, 160))
        end
    end
    return true, nil
end

function ConfigManager:reset()
    self._values = ConfigDefaults.normalize({})
    for _, listener in ipairs(self._listeners) do
        pcall(listener, "*", nil)
    end
end

function ConfigManager:subscribe(callback: (...any) -> ()): () -> ()
    table.insert(self._listeners, callback)
    return function()
        for index = #self._listeners, 1, -1 do
            if self._listeners[index] == callback then
                table.remove(self._listeners, index)
            end
        end
    end
end

function ConfigManager:snapshot(): table
    return ConfigDefaults.copy(self._values)
end

return ConfigManager
end

__modules["Shared.DedupeCache"] = function()
--!nonstrict
-- Bounded time-to-live cache used for collected collectibles and idempotent
-- request IDs. It is intentionally small: memory is capped whether or not a
-- caller ever purges it.

local DedupeCache = {}
DedupeCache.__index = DedupeCache

function DedupeCache.new(ttlSeconds: number, maximumEntries: number)
    assert(ttlSeconds > 0, "ttlSeconds must be positive")
    assert(maximumEntries > 0, "maximumEntries must be positive")
    local self = setmetatable({}, DedupeCache)
    self.ttl = ttlSeconds
    self.maximumEntries = maximumEntries
    self.entries = {}
    self.sequence = 0
    return self
end

function DedupeCache:_removeExpired(now: number)
    for key, entry in pairs(self.entries) do
        if now >= entry.expiresAt then
            self.entries[key] = nil
        end
    end
end

function DedupeCache:_makeSpace()
    local count = 0
    local oldestKey = nil
    local oldestSequence = math.huge
    for key, entry in pairs(self.entries) do
        count += 1
        if entry.sequence < oldestSequence then
            oldestSequence = entry.sequence
            oldestKey = key
        end
    end
    if count >= self.maximumEntries and oldestKey ~= nil then
        self.entries[oldestKey] = nil
    end
end

function DedupeCache:get(key: string, now: number): (boolean, any)
    self:_removeExpired(now)
    local entry = self.entries[key]
    if not entry then
        return false, nil
    end
    return true, entry.value
end

function DedupeCache:put(key: string, value: any, now: number)
    self:_removeExpired(now)
    if self.entries[key] == nil then
        self:_makeSpace()
    end
    self.sequence += 1
    self.entries[key] = {
        value = value,
        expiresAt = now + self.ttl,
        sequence = self.sequence,
    }
end

function DedupeCache:purge(now: number)
    self:_removeExpired(now)
end

function DedupeCache:size(now: number): number
    self:_removeExpired(now)
    local count = 0
    for _ in pairs(self.entries) do
        count += 1
    end
    return count
end

return DedupeCache
end

__modules["Shared.Diagnostics"] = function()
--!nonstrict
-- In-memory diagnostic log. It never records credentials, session tokens, raw
-- remote errors, or player names. Entries are bounded and truncated.

local Validation = __require("Shared.Validation")

local Diagnostics = {}
Diagnostics.__index = Diagnostics

function Diagnostics.new(options: any?)
    local settings = options or {}
    local self = setmetatable({}, Diagnostics)
    self.maxEntries = math.max(20, tonumber(settings.maxEntries) or 200)
    self.clock = settings.clock or os.clock
    self.debugEnabled = settings.debug == true
    self.sink = settings.sink
    self._entries = {}
    self._sequence = 0
    return self
end

function Diagnostics:setDebug(enabled: boolean)
    self.debugEnabled = enabled == true
end

function Diagnostics:isDebug(): boolean
    return self.debugEnabled
end

function Diagnostics:_write(level: string, message: any)
    if level == "debug" and not self.debugEnabled then
        return
    end

    local text = Validation.cleanText(tostring(message or ""), 300) or "(empty message)"
    self._sequence += 1
    table.insert(self._entries, {
        level = level,
        text = text,
        at = self.clock(),
        sequence = self._sequence,
    })

    while #self._entries > self.maxEntries do
        table.remove(self._entries, 1)
    end

    if self.sink and (level ~= "debug" or self.debugEnabled) then
        pcall(self.sink, level, text)
    end
end

function Diagnostics:debug(message: any)
    self:_write("debug", message)
end

function Diagnostics:info(message: any)
    self:_write("info", message)
end

function Diagnostics:warn(message: any)
    self:_write("warn", message)
end

function Diagnostics:error(message: any)
    self:_write("error", message)
end

function Diagnostics:entries(): { any }
    local copy = table.create(#self._entries)
    for index, entry in ipairs(self._entries) do
        copy[index] = {
            level = entry.level,
            text = entry.text,
            at = entry.at,
            sequence = entry.sequence,
        }
    end
    return copy
end

function Diagnostics:format(limit: number?): string
    local count = limit or 12
    local lines = {}
    local start = math.max(1, #self._entries - count + 1)
    for index = start, #self._entries do
        local entry = self._entries[index]
        table.insert(lines, string.format("[%s] %s", string.upper(entry.level), entry.text))
    end
    if #lines == 0 then
        return "No diagnostic entries."
    end
    return table.concat(lines, "\n")
end

function Diagnostics:counts(): (number, number, number, number)
    local debugCount, infoCount, warnCount, errorCount = 0, 0, 0, 0
    for _, entry in ipairs(self._entries) do
        if entry.level == "debug" then
            debugCount += 1
        elseif entry.level == "info" then
            infoCount += 1
        elseif entry.level == "warn" then
            warnCount += 1
        elseif entry.level == "error" then
            errorCount += 1
        end
    end
    return debugCount, infoCount, warnCount, errorCount
end

function Diagnostics:clear()
    self._entries = {}
    self._sequence = 0
end

function Diagnostics:hasErrors(): boolean
    for _, entry in ipairs(self._entries) do
        if entry.level == "error" then
            return true
        end
    end
    return false
end

return Diagnostics
end

__modules["Shared.EnvironmentSchema"] = function()
--!nonstrict
-- Strict client-side validation for the environment handshake. The client never
-- trusts the shape of a server response; malformed data becomes a clear
-- diagnostic instead of an error deep inside a feature module.

local Protocol = __require("Shared.Protocol")
local Validation = __require("Shared.Validation")

local EnvironmentSchema = {}

local VALID_SCOPES = { none = true, studio = true, place = true }
local LIMIT_RANGES = {
    moneyMaxDistance = { 100, 10000 },
    atmRange = { 1, 100 },
    atmCooldown = { 0.1, 60 },
    combatRange = { 1, 500 },
    noclipMaxDuration = { 5, 600 },
}

local function fail(reason: string): (false, nil, string)
    return false, nil, reason
end

local function finite(value: any, minimum: number, maximum: number): boolean
    return type(value) == "number"
        and value == value
        and value ~= math.huge
        and value ~= -math.huge
        and value >= minimum
        and value <= maximum
end

function EnvironmentSchema.validate(raw: any): (boolean, table?, string?)
    if type(raw) ~= "table" then
        return fail("Environment response was not a table.")
    end
    if raw.protocol ~= Protocol.PROTOCOL then
        return fail("Protocol mismatch: expected " .. tostring(Protocol.PROTOCOL) .. ".")
    end
    if type(raw.authorized) ~= "boolean" then
        return fail("Environment authorization flag was missing.")
    end
    if type(raw.code) ~= "string" or raw.code == "" then
        return fail("Environment result code was missing.")
    end
    if not VALID_SCOPES[raw.scope] then
        return fail("Environment authorization scope was invalid.")
    end
    if raw.authorized and raw.scope == "none" then
        return fail("Environment claimed authorization without a scope.")
    end
    if raw.authorized and raw.code ~= "OK" then
        return fail("Environment claimed authorization with a failure code.")
    end
    if not raw.authorized and raw.code == "OK" then
        return fail("Environment returned OK without authorization.")
    end

    local features = {}
    if type(raw.features) ~= "table" then
        return fail("Environment feature table was missing.")
    end
    for _, feature in ipairs(Protocol.FEATURES) do
        local value = raw.features[feature]
        if type(value) ~= "boolean" then
            return fail("Environment feature '" .. feature .. "' was not a boolean.")
        end
        features[feature] = value
    end

    local limits = {}
    if type(raw.limits) ~= "table" then
        return fail("Environment limits were missing.")
    end
    for name, range in pairs(LIMIT_RANGES) do
        local value = raw.limits[name]
        if not finite(value, range[1], range[2]) then
            return fail("Environment limit '" .. name .. "' was invalid.")
        end
        limits[name] = value
    end

    local serverVersion = Validation.cleanText(raw.serverVersion, 32)
    if not serverVersion then
        return fail("Environment server version was missing.")
    end
    local message = Validation.cleanText(raw.message, 240) or Protocol.message(raw.code)

    return true, {
        protocol = raw.protocol,
        serverVersion = serverVersion,
        authorized = raw.authorized,
        code = Validation.cleanText(raw.code, 64) or "INVALID_ENVIRONMENT",
        message = message,
        scope = raw.scope,
        features = features,
        limits = limits,
        fixturesReady = raw.fixturesReady == true,
        receivedAt = os.clock(),
    }, nil
end

function EnvironmentSchema.featuresFromSnapshot(snapshot: table?): table
    local features = {}
    for _, feature in ipairs(Protocol.FEATURES) do
        features[feature] = snapshot ~= nil and snapshot.features ~= nil and snapshot.features[feature] == true
    end
    return features
end

return EnvironmentSchema
end

__modules["Shared.MockLedger"] = function()
--!nonstrict
-- In-memory development ledger. This is NOT Robux, leaderstats, DataStore, or
-- any real game currency. It exists only so authorized fixtures and ATM tests
-- have an auditable server-side balance to display.

local Validation = __require("Shared.Validation")

local MockLedger = {}
MockLedger.__index = MockLedger

function MockLedger.new(initialBalance: number?, maximumBalance: number?)
    local self = setmetatable({}, MockLedger)
    self.initialBalance = math.max(0, math.floor(initialBalance or 0))
    self.maximumBalance = math.max(self.initialBalance, math.floor(maximumBalance or 1000000))
    self.balances = {}
    self.entries = {}
    self.entryLimit = 20
    return self
end

function MockLedger:get(userId: number): number
    local key = tostring(userId)
    local balance = self.balances[key]
    if balance == nil then
        return self.initialBalance
    end
    return balance
end

local function validAmount(amount: any): boolean
    -- Credits are whole units. Rejecting fractions prevents a sub-unit credit
    -- from succeeding while flooring to zero in the ledger.
    return Validation.isFiniteNumber(amount) and amount >= 1 and amount <= 1000000
end

function MockLedger:credit(userId: number, amount: number, meta: any?): (boolean, number, string?)
    if not validAmount(amount) then
        return false, self:get(userId), "INVALID_AMOUNT"
    end

    local key = tostring(userId)
    local current = self:get(userId)
    local nextBalance = current + math.floor(amount)
    if nextBalance > self.maximumBalance then
        return false, current, "BALANCE_LIMIT"
    end

    self.balances[key] = nextBalance

    local list = self.entries[key]
    if not list then
        list = {}
        self.entries[key] = list
    end
    table.insert(list, {
        amount = math.floor(amount),
        balance = nextBalance,
        reason = Validation.cleanText(meta and meta.reason, 40) or "test",
        requestId = Validation.id(meta and meta.requestId, 6, 80),
        at = os.clock(),
    })
    while #list > self.entryLimit do
        table.remove(list, 1)
    end

    return true, nextBalance, nil
end

function MockLedger:reset(userId: number?): number
    if userId == nil then
        self.balances = {}
        self.entries = {}
        return self.initialBalance
    end
    local key = tostring(userId)
    self.balances[key] = nil
    self.entries[key] = nil
    return self.initialBalance
end

function MockLedger:recent(userId: number): { any }
    local list = self.entries[tostring(userId)]
    if not list then
        return {}
    end
    local copy = table.create(#list)
    for index, entry in ipairs(list) do
        copy[index] = {
            amount = entry.amount,
            balance = entry.balance,
            reason = entry.reason,
            requestId = entry.requestId,
            at = entry.at,
        }
    end
    return copy
end

return MockLedger
end

__modules["Shared.MoneyDiagnostics"] = function()
--!nonstrict
-- Bounded, human-readable diagnostics for the money collector. The UI reads
-- only this snapshot. Nothing here includes player names, account IDs, tokens,
-- or raw server errors from third-party code.

local Validation = __require("Shared.Validation")

local MoneyDiagnostics = {}
MoneyDiagnostics.__index = MoneyDiagnostics

local STATES = {
    stopped = true,
    starting = true,
    running = true,
    paused = true,
    unavailable = true,
}

function MoneyDiagnostics.new(options: any?)
    local settings = options or {}
    local self = setmetatable({}, MoneyDiagnostics)
    self.clock = settings.clock or os.clock
    self.moduleState = "stopped"
    self.radius = settings.radius or 10000
    self.eligibleCount = 0
    self.apiAvailable = false
    self.apiDetail = "Not checked."
    self.lastSuccess = "None this session."
    self.lastSuccessAt = nil
    self.lastError = "None this session."
    self.lastErrorAt = nil
    self.requests = 0
    self.successes = 0
    self.failures = 0
    self.collectedTotal = 0
    return self
end

function MoneyDiagnostics:setModuleState(state: string)
    if type(state) ~= "string" or not STATES[state] then
        state = "unavailable"
    end
    self.moduleState = state
end

function MoneyDiagnostics:getModuleState(): string
    return self.moduleState
end

function MoneyDiagnostics:setRadius(radius: number)
    if Validation.isFiniteNumber(radius) and radius > 0 then
        self.radius = radius
    end
end

function MoneyDiagnostics:setEligibleCount(count: number)
    if Validation.isFiniteNumber(count) and count >= 0 then
        self.eligibleCount = math.floor(count)
    end
end

function MoneyDiagnostics:setApiAvailable(available: boolean, detail: string?)
    self.apiAvailable = available == true
    self.apiDetail = Validation.cleanText(detail, 180) or (self.apiAvailable and "Available." or "Unavailable.")
end

function MoneyDiagnostics:recordRequest()
    self.requests += 1
end

function MoneyDiagnostics:recordSuccess(data: table?)
    local info = data or {}
    self.successes += 1
    local value = tonumber(info.value)
    if value and Validation.isFiniteNumber(value) then
        self.collectedTotal += value
    end
    local amount = value and ("+" .. tostring(math.floor(value))) or "collected"
    local balance = tonumber(info.balance)
    local suffix = balance and (" · test balance " .. tostring(math.floor(balance))) or ""
    self.lastSuccess = Validation.cleanText(amount .. " · " .. tostring(info.itemName or "test pickup") .. suffix, 160)
        or "Collect succeeded."
    self.lastSuccessAt = self.clock()
end

function MoneyDiagnostics:recordError(reason: string?)
    self.failures += 1
    self.lastError = Validation.cleanText(reason, 180) or "Unknown collection error."
    self.lastErrorAt = self.clock()
end

local function ageText(now: number, at: number?): string
    if not at then
        return "never"
    end
    return Validation.truncate(("%.1fs ago"):format(math.max(0, now - at)), 24)
end

function MoneyDiagnostics:snapshot(): table
    local now = self.clock()
    return {
        moduleState = self.moduleState,
        radius = self.radius,
        eligibleCount = self.eligibleCount,
        apiAvailable = self.apiAvailable,
        apiDetail = self.apiDetail,
        lastSuccess = self.lastSuccess,
        lastSuccessAge = ageText(now, self.lastSuccessAt),
        lastError = self.lastError,
        lastErrorAge = ageText(now, self.lastErrorAt),
        requests = self.requests,
        successes = self.successes,
        failures = self.failures,
        collectedTotal = self.collectedTotal,
    }
end

function MoneyDiagnostics:format(): string
    local s = self:snapshot()
    return string.format(
        "Module: %s  ·  radius: %s\nEligible nearby: %d  ·  API: %s\nAPI detail: %s\nLast success: %s (%s)\nLast error: %s (%s)\nRequests: %d  ·  successes: %d  ·  failures: %d",
        string.upper(s.moduleState),
        tostring(math.floor(s.radius)),
        s.eligibleCount,
        s.apiAvailable and "available" or "unavailable",
        s.apiDetail,
        s.lastSuccess,
        s.lastSuccessAge,
        s.lastError,
        s.lastErrorAge,
        s.requests,
        s.successes,
        s.failures
    )
end

return MoneyDiagnostics
end

__modules["Shared.Payloads"] = function()
--!nonstrict
-- Strict, side-effect-free request validators. A malformed payload fails here
-- before any feature service touches the world or the mock ledger.
--
-- Transport envelope:
--   { requestId = "req_...", payload = { ... } }
-- The request ID is the server idempotency key. It is never accepted from
-- attributes or from another table depth.

local Validation = __require("Shared.Validation")

local Payloads = {}
local MIN_ID = 6
local MAX_ID = 80

local function reject(code: string): (false, nil, string)
    return false, nil, code
end

local function safeTable(value: any): boolean
    return Validation.safeTable(value)
end

function Payloads.envelope(raw: any): (boolean, table?, string?)
    if not safeTable(raw) then
        return reject("INVALID_PAYLOAD")
    end
    -- The transport envelope is exact. Extra top-level keys are rejected so a
    -- caller cannot smuggle fields alongside the two validated fields.
    local keyCount = 0
    for key in pairs(raw) do
        if key ~= "requestId" and key ~= "payload" then
            return reject("INVALID_PAYLOAD")
        end
        keyCount += 1
    end
    if keyCount ~= 2 then
        return reject("INVALID_PAYLOAD")
    end
    local requestId = Validation.id(raw.requestId, MIN_ID, MAX_ID)
    if not requestId or not safeTable(raw.payload) then
        return reject("INVALID_PAYLOAD")
    end
    return true, {
        requestId = requestId,
        payload = raw.payload,
    }, nil
end

function Payloads.collect(payload: any): (boolean, table?, string?)
    if not safeTable(payload) then
        return reject("INVALID_PAYLOAD")
    end
    local id = Validation.id(payload.collectibleId, MIN_ID, MAX_ID)
    if not id then
        return reject("INVALID_PAYLOAD")
    end
    return true, { collectibleId = id }, nil
end

function Payloads.atm(payload: any): (boolean, table?, string?)
    if not safeTable(payload) then
        return reject("INVALID_PAYLOAD")
    end
    local atmId = Validation.id(payload.atmId, MIN_ID, MAX_ID)
    local mode = payload.mode
    if not atmId then
        return reject("INVALID_PAYLOAD")
    end
    if mode ~= "validate" and mode ~= "mock" then
        return reject("INVALID_PAYLOAD")
    end
    return true, {
        atmId = atmId,
        mode = mode,
    }, nil
end

function Payloads.combat(payload: any): (boolean, table?, string?)
    if not safeTable(payload) then
        return reject("INVALID_PAYLOAD")
    end
    local targetId = Validation.id(payload.targetId, MIN_ID, MAX_ID)
    -- Combat Test Mode only addresses server-created dummy fixtures. Reject
    -- player or arbitrary instance IDs before the service lookup as defence in
    -- depth; CombatService still verifies tags, ownership and approval.
    if not targetId or string.sub(targetId, 1, 6) ~= "dummy_" then
        return reject("INVALID_PAYLOAD")
    end
    return true, {
        targetId = targetId,
    }, nil
end

function Payloads.noclip(payload: any): (boolean, table?, string?)
    if not safeTable(payload) then
        return reject("INVALID_PAYLOAD")
    end
    local action = payload.action
    if action ~= "enable" and action ~= "disable" and action ~= "status" then
        return reject("INVALID_PAYLOAD")
    end
    return true, { action = action }, nil
end

return Payloads
end

