__modules["Shared.RateLimiter"] = function()
--!nonstrict
-- Monotonic-time token bucket and debouncer. Callers pass `now` so the logic is
-- deterministic in tests and so no module needs to run its own polling loop.

local RateLimiter = {}
RateLimiter.__index = RateLimiter

function RateLimiter.new(capacity: number, refillPerSecond: number)
    assert(capacity > 0, "capacity must be positive")
    assert(refillPerSecond > 0, "refillPerSecond must be positive")

    local self = setmetatable({}, RateLimiter)
    self.capacity = capacity
    self.refillPerSecond = refillPerSecond
    self.tokens = capacity
    self.updatedAt = nil
    return self
end

function RateLimiter:_refill(now: number)
    if self.updatedAt == nil then
        self.updatedAt = now
        return
    end
    local elapsed = now - self.updatedAt
    if elapsed <= 0 then
        self.updatedAt = math.max(self.updatedAt, now)
        return
    end
    self.tokens = math.min(self.capacity, self.tokens + elapsed * self.refillPerSecond)
    self.updatedAt = now
end

function RateLimiter:tryConsume(now: number, cost: number?): (boolean, number)
    local amount = cost or 1
    if amount <= 0 then
        return false, self.tokens
    end
    self:_refill(now)
    if self.tokens >= amount then
        self.tokens -= amount
        return true, self.tokens
    end
    return false, self.tokens
end

function RateLimiter:getTokens(now: number): number
    self:_refill(now)
    return self.tokens
end

function RateLimiter:getRetryAfter(now: number, cost: number?): number
    local amount = cost or 1
    self:_refill(now)
    if self.tokens >= amount then
        return 0
    end
    return (amount - self.tokens) / self.refillPerSecond
end

function RateLimiter:reset()
    self.tokens = self.capacity
    self.updatedAt = nil
end

local Debouncer = {}
Debouncer.__index = Debouncer

function Debouncer.new(interval: number)
    assert(interval >= 0, "interval must not be negative")
    local self = setmetatable({}, Debouncer)
    self.interval = interval
    self.lastAt = nil
    return self
end

function Debouncer:isReady(now: number): boolean
    if self.lastAt == nil or now - self.lastAt >= self.interval then
        self.lastAt = now
        return true
    end
    return false
end

function Debouncer:remaining(now: number): number
    if self.lastAt == nil then
        return 0
    end
    return math.max(0, self.interval - (now - self.lastAt))
end

return {
    RateLimiter = RateLimiter,
    Debouncer = Debouncer,
}
end

__modules["Shared.Scheduler"] = function()
--!nonstrict
-- Deterministic update scheduler. The client runtime drives :update from one
-- Heartbeat connection, which keeps module scans on one controlled cadence and
-- makes this module directly unit testable with a fake clock.

local Scheduler = {}
Scheduler.__index = Scheduler

function Scheduler.new(options: any?)
    local settings = options or {}
    local self = setmetatable({}, Scheduler)
    self.clock = settings.clock or os.clock
    self.onError = settings.onError
    self.tasks = {}
    return self
end

local function checkName(name: any)
    assert(type(name) == "string" and name ~= "", "scheduler task name must be a non-empty string")
end

function Scheduler:every(name: string, interval: number, callback: (number) -> (), immediate: boolean?): boolean
    checkName(name)
    assert(type(interval) == "number" and interval > 0 and interval == interval, "interval must be positive")
    assert(type(callback) == "function", "callback must be a function")

    if self.tasks[name] then
        return false
    end

    local now = self.clock()
    self.tasks[name] = {
        interval = interval,
        callback = callback,
        nextAt = immediate == false and (now + interval) or now,
        runs = 0,
        errors = 0,
        lastError = nil,
    }
    return true
end

function Scheduler:cancel(name: string): boolean
    if self.tasks[name] == nil then
        return false
    end
    self.tasks[name] = nil
    return true
end

function Scheduler:isRunning(name: string): boolean
    return self.tasks[name] ~= nil
end

function Scheduler:update(now: number?)
    local currentTime = now or self.clock()
    local due = {}
    for name, task in pairs(self.tasks) do
        if currentTime >= task.nextAt then
            table.insert(due, { name = name, task = task })
        end
    end
    table.sort(due, function(left, right)
        if left.task.nextAt == right.task.nextAt then
            return left.name < right.name
        end
        return left.task.nextAt < right.task.nextAt
    end)

    for _, entry in ipairs(due) do
        -- A callback may cancel or replace tasks. Only run the task that was
        -- actually scheduled for this tick.
        if self.tasks[entry.name] == entry.task then
            entry.task.runs += 1
            -- Deliberately do not catch up missed ticks in a burst. A slow
            -- frame should delay a scan, not stack all missed scans.
            entry.task.nextAt = currentTime + entry.task.interval

            local ok, err = pcall(entry.task.callback, currentTime)
            if not ok then
                entry.task.errors += 1
                entry.task.lastError = tostring(err)
                if type(self.onError) == "function" then
                    pcall(self.onError, entry.name, err)
                end
            end
        end
    end
end

function Scheduler:clear()
    self.tasks = {}
end

function Scheduler:count(): number
    local total = 0
    for _ in pairs(self.tasks) do
        total += 1
    end
    return total
end

function Scheduler:describe(): string
    local names = {}
    for name, task in pairs(self.tasks) do
        table.insert(names, string.format("%s (%d runs, %d errors)", name, task.runs, task.errors))
    end
    table.sort(names)
    if #names == 0 then
        return "No scheduled tasks."
    end
    return table.concat(names, "\n")
end

return Scheduler
end

