__modules["Shared.Util"] = function()
--!nonstrict
-- Formatting, identifiers and small helpers. This module only depends on
-- ordinary Luau data so it can be unit tested outside Roblox.

local Util = {}

local requestCounter = 0

function Util.formatNumber(value: number, decimals: number?): string
    local places = math.max(0, math.floor(decimals or 0))
    local negative = value < 0
    local formatted = string.format("%." .. tostring(places) .. "f", math.abs(value))
    local whole, fraction = string.match(formatted, "^(%d+)(%.?.*)$")
    whole = whole or formatted
    fraction = fraction or ""
    local groups = {}
    while #whole > 3 do
        table.insert(groups, 1, string.sub(whole, -3))
        whole = string.sub(whole, 1, -4)
    end
    table.insert(groups, 1, whole)
    return (negative and "-" or "") .. table.concat(groups, ",") .. fraction
end

function Util.formatDistance(studs: number): string
    if not (type(studs) == "number" and studs == studs) then
        return "?"
    end
    if studs >= 1000 then
        return Util.formatNumber(studs / 1000, studs >= 10000 and 0 or 1) .. "k studs"
    end
    return Util.formatNumber(studs, 0) .. " studs"
end

function Util.formatDuration(seconds: number): string
    if not (type(seconds) == "number" and seconds == seconds) or seconds < 0 then
        return "?"
    end
    if seconds < 1 then
        return string.format("%.1fs", seconds)
    end
    local total = math.floor(seconds + 0.5)
    if total < 60 then
        return tostring(total) .. "s"
    end
    local minutes = math.floor(total / 60)
    local remainder = total % 60
    if minutes < 60 then
        return string.format("%dm %02ds", minutes, remainder)
    end
    return string.format("%dh %02dm", math.floor(minutes / 60), minutes % 60)
end

-- Request IDs are not secrets. They are short, readable correlation tokens so
-- the server can make retries idempotent and clients can match responses.
function Util.requestId(prefix: string?): string
    requestCounter += 1
    local safePrefix = string.gsub(string.lower(tostring(prefix or "req")), "[^%w_%-]", "")
    safePrefix = string.sub(safePrefix ~= "" and safePrefix or "req", 1, 12)
    local randomPart
    if Random then
        local rng = Random.new()
        randomPart = string.format("%08x%08x", rng:NextInteger(0, 0x7FFFFFFF), rng:NextInteger(0, 0x7FFFFFFF))
    else
        -- Stay within the signed 32-bit range accepted by Luau's math.random.
        -- Using 0xFFFFFFFF as an upper bound is rejected as an empty interval.
        randomPart = string.format("%08x%08x", math.random(0, 0x7FFFFFFF), math.random(0, 0x7FFFFFFF))
    end
    return string.format("req_%s_%08x_%s", safePrefix, requestCounter % 0xFFFFFFFF, randomPart)
end

function Util.countEntries(tbl: table?): number
    if type(tbl) ~= "table" then
        return 0
    end
    local count = 0
    for _ in pairs(tbl) do
        count += 1
    end
    return count
end

function Util.safeCall(callback: any, ...)
    if type(callback) ~= "function" then
        return false, "callback is not a function"
    end
    return pcall(callback, ...)
end

function Util.joined(...): string
    local parts = {}
    for index = 1, select("#", ...) do
        local value = select(index, ...)
        if value ~= nil and tostring(value) ~= "" then
            table.insert(parts, tostring(value))
        end
    end
    return table.concat(parts, " · ")
end

function Util.isPlayerCharacter(instance: Instance?): boolean
    if not instance then
        return false
    end
    local players = game:GetService("Players")
    local current = instance
    while current and current ~= workspace do
        if current:IsA("Model") then
            local player = players:GetPlayerFromCharacter(current)
            if player then
                return true
            end
        end
        current = current.Parent
    end
    return false
end

return Util
end

__modules["Shared.Validation"] = function()
--!nonstrict
-- Small, deterministic validation helpers. These are used by both the client
-- configuration layer and the server request validators. They do not throw.

local Validation = {}

function Validation.isFiniteNumber(value: any): boolean
    return type(value) == "number"
        and value == value
        and value ~= math.huge
        and value ~= -math.huge
end

function Validation.isInteger(value: any): boolean
    return Validation.isFiniteNumber(value) and value % 1 == 0
end

-- Returns value or default, plus a flag indicating whether the value was
-- adjusted. Numbers that are malformed (not finite) fall back to the default.
function Validation.number(value: any, default: number, minimum: number?, maximum: number?)
    if not Validation.isFiniteNumber(value) then
        return default, false
    end
    local low = minimum or -math.huge
    local high = maximum or math.huge
    if low > high then
        low, high = high, low
    end
    local clamped = math.clamp(value, low, high)
    return clamped, clamped ~= value
end

-- Strict numeric parse for request payloads. Returns nil and a reason instead
-- of silently changing a client-supplied value.
function Validation.strictNumber(value: any, minimum: number, maximum: number, integerOnly: boolean?): (number?, string?)
    if not Validation.isFiniteNumber(value) then
        return nil, "not a finite number"
    end
    if integerOnly and value % 1 ~= 0 then
        return nil, "not an integer"
    end
    if value < minimum or value > maximum then
        return nil, "out of range"
    end
    return value, nil
end

function Validation.boolean(value: any, default: boolean): boolean
    if type(value) == "boolean" then
        return value
    end
    return default
end

function Validation.oneOf(value: any, options: { string }, default: string): (string, boolean)
    if type(value) == "string" then
        for _, option in ipairs(options) do
            if option == value then
                return option, false
            end
        end
    end
    return default, true
end

function Validation.hasOption(options: { string }, value: any): boolean
    if type(value) ~= "string" then
        return false
    end
    for _, option in ipairs(options) do
        if option == value then
            return true
        end
    end
    return false
end

-- Removes control characters, collapses whitespace, and caps length. Returns
-- nil for values that are not strings or become empty.
function Validation.cleanText(value: any, maximumLength: number?): string?
    if type(value) ~= "string" then
        return nil
    end
    local text = string.gsub(value, "[%c]", " ")
    text = string.gsub(text, "%s+", " ")
    text = string.gsub(text, "^%s*(.-)%s*$", "%1")
    local limit = maximumLength or 200
    if #text > limit then
        text = string.sub(text, 1, limit)
    end
    if text == "" then
        return nil
    end
    return text
end

-- Identifiers are generated by us and have a deliberately narrow alphabet.
-- Rejecting whitespace, dots, slashes and control characters prevents path-like
-- or display-injection payloads from reaching logs or the UI.
function Validation.id(value: any, minimumLength: number?, maximumLength: number?): string?
    if type(value) ~= "string" then
        return nil
    end
    local low = minimumLength or 6
    local high = maximumLength or 80
    if #value < low or #value > high then
        return nil
    end
    if not string.match(value, "^[%w_%-]+$") then
        return nil
    end
    return value
end

function Validation.safeTable(value: any): boolean
    return type(value) == "table" and getmetatable(value) == nil
end

function Validation.truncate(value: any, maximumLength: number): string
    local text = tostring(value or "")
    if #text > maximumLength then
        return string.sub(text, 1, maximumLength) .. "..."
    end
    return text
end

return Validation
end

__modules["Client.ATMInteractionTest"] = function()
--!nonstrict
-- ATM Auto Interaction Test. Every successful action is a server-validated mock
-- ledger entry. "mock" mode is bounded by a per-session credit cap and a server
-- cooldown. It cannot create real currency or the third-party game's money.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")

local Protocol = __require("Shared.Protocol")
local Validation = __require("Shared.Validation")

local ATMInteractionTest = {}
ATMInteractionTest.__index = ATMInteractionTest

local FATAL_CODES = {
    SERVER_COMPONENT_MISSING = true,
    REMOTE_MISSING = true,
    PLACE_NOT_AUTHORIZED = true,
    TESTER_NOT_AUTHORIZED = true,
    TESTER_ALLOWLIST_EMPTY = true,
    ENVIRONMENT_NOT_READY = true,
    FEATURE_DISABLED = true,
    FIXTURES_NOT_READY = true,
    SERVICE_UNAVAILABLE = true,
    ATM_MODE_DISABLED = true,
    TEST_CREDIT_CAP = true,
    BALANCE_CAP = true,
    CHARACTER_UNAVAILABLE = true,
}

function ATMInteractionTest.new(options: table)
    local self = setmetatable({}, ATMInteractionTest)
    self.scheduler = options.scheduler
    self.remote = options.remote
    self.environment = options.environment
    self.config = options.config
    self.logger = options.logger
    self.onAutoStopped = options.onAutoStopped
    self.running = false
    self.inFlight = false
    self.attempts = 0
    self.successes = 0
    self.failures = 0
    self.lastResult = "None this session."
    self.lastBalance = nil
    self._taskName = "atm.auto"
    return self
end

local function characterRoot(): BasePart?
    local character = Players.LocalPlayer and Players.LocalPlayer.Character
    if not character then
        return nil
    end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if humanoid and humanoid.Health <= 0 then
        return nil
    end
    local root = character:FindFirstChild("HumanoidRootPart")
    return root and root:IsA("BasePart") and root or nil
end

local function findATMs(root: BasePart, range: number): { table }
    local list = {}
    for _, instance in ipairs(CollectionService:GetTagged(Protocol.TAGS.ATM)) do
        if instance:IsDescendantOf(workspace)
            and instance:GetAttribute(Protocol.ATTRIBUTES.Fixture) == true
        then
            local id = Validation.id(instance:GetAttribute(Protocol.ATTRIBUTES.AtmId), Protocol.IDS.MinLength, Protocol.IDS.MaxLength)
            local position = nil
            if instance:IsA("BasePart") then
                position = instance.Position
            elseif instance:IsA("Model") then
                local primary = instance.PrimaryPart or instance:FindFirstChildWhichIsA("BasePart", true)
                position = primary and primary.Position or nil
            end
            if id and position then
                local distance = (root.Position - position).Magnitude
                if distance <= range then
                    table.insert(list, { instance = instance, id = id, distance = distance })
                end
            end
        end
    end
    table.sort(list, function(left, right)
        return left.distance < right.distance
    end)
    return list
end

function ATMInteractionTest:_setResult(text: string)
    self.lastResult = Validation.cleanText(text, 180) or "Unknown result."
end

function ATMInteractionTest:_apiAvailability(): (boolean, string?)
    local snapshot = self.environment:getSnapshot()
    if not self.remote:isAvailable() then
        return false, "REMOTE_MISSING"
    end
    if not snapshot then
        return false, "ENVIRONMENT_NOT_READY"
    end
    if not snapshot.authorized then
        return false, snapshot.code
    end
    if not snapshot.features.ATM then
        if not snapshot.fixturesReady then
            return false, "FIXTURES_NOT_READY"
        end
        return false, "FEATURE_DISABLED"
    end
    return true, nil
end

function ATMInteractionTest:_handleResult(response: table, automatic: boolean)
    self.inFlight = false
    if response.ok then
        self.successes += 1
        local data = response.data or {}
        self.lastBalance = data.balance
        self:_setResult(string.format(
            "%s · credited %s · test balance %s · %s credits left",
            tostring(data.mode or "validate"),
            tostring(data.credited or 0),
            tostring(data.balance or "?"),
            tostring(data.remainingTestCredits or "?")
        ))
        return
    end

    self.failures += 1
    self:_setResult(Protocol.message(response.code))
    if automatic and FATAL_CODES[response.code] then
        if self.running then
            self:stop()
        end
        if self.onAutoStopped then
            pcall(self.onAutoStopped, response.code)
        end
    end
end

function ATMInteractionTest:_send(atmId: string, automatic: boolean): (boolean, string?)
    if self.inFlight then
        return false, "REMOTE_BUSY"
    end
    self.inFlight = true
    self.attempts += 1
    local mode = self.config:getValue("ATM.Mode")
    local requestId, errorCode = self.remote:request("ATM", {
        atmId = atmId,
        mode = mode,
    }, function(response)
        self:_handleResult(response, automatic)
    end)
    if not requestId then
        self.inFlight = false
        self:_setResult(Protocol.message(errorCode or "REMOTE_INVOKE_FAILED"))
        return false, errorCode or "REMOTE_INVOKE_FAILED"
    end
    return true, nil
end

function ATMInteractionTest:_scan(automatic: boolean): (boolean, string?)
    local root = characterRoot()
    if not root then
        return false, "CHARACTER_UNAVAILABLE"
    end
    local available, code = self:_apiAvailability()
    if not available then
        return false, code
    end

    local range = self.environment:getLimit("atmRange", Protocol.LIMIT_DEFAULTS.atmRange)
    local atms = findATMs(root, range)
    if #atms == 0 then
        self:_setResult("No tagged test ATM in range.")
        return false, "NO_TARGET"
    end
    return self:_send(atms[1].id, automatic)
end

function ATMInteractionTest:_schedule()
    self.scheduler:cancel(self._taskName)
    local interval = self.config:getValue("ATM.Interval")
    self.scheduler:every(self._taskName, interval, function()
        local ok, err = pcall(function()
            self:_scan(true)
        end)
        if not ok then
            self.failures += 1
            self:_setResult(Validation.truncate(err, 160))
            self.logger:warn("ATM test scan failed: " .. Validation.truncate(err, 160))
        end
    end, true)
end

function ATMInteractionTest:start(): (boolean, string?)
    if self.running then
        return true, nil
    end
    if not Players.LocalPlayer then
        return false, "CHARACTER_UNAVAILABLE"
    end
    local reason = self.environment:featureReason("ATM", true)
    if reason then
        return false, reason
    end
    if not self.remote:isAvailable() then
        return false, self.remote:getReason() or "REMOTE_MISSING"
    end
    self.running = true
    self.inFlight = false
    self:_schedule()
    return true, nil
end

function ATMInteractionTest:stop()
    self.running = false
    self.scheduler:cancel(self._taskName)
end

function ATMInteractionTest:interactOnce(): (boolean, string?)
    local reason = self.environment:featureReason("ATM", true)
    if reason then
        return false, reason
    end
    if self.inFlight then
        return false, "REMOTE_BUSY"
    end
    return self:_scan(false)
end

function ATMInteractionTest:applyConfig()
    if self.running then
        self:_schedule()
    end
end

function ATMInteractionTest:isRunning(): boolean
    return self.running
end

function ATMInteractionTest:getStatusText(): string
    local state = self.running and "running" or "stopped"
    local mode = self.config:getValue("ATM.Mode")
    return string.format("%s · mode %s · %d requests · %d accepted", state, mode, self.attempts, self.successes)
end

function ATMInteractionTest:getDetailText(): string
    return string.format("Last result: %s\nFailures/rejections: %d\nServer cooldown: %.1fs", self.lastResult, self.failures, self.environment:getLimit("atmCooldown", 0))
end

return ATMInteractionTest
end

__modules["Client.Boot"] = function()
--!nonstrict
-- Client entry point. Boot owns the single-run guard and the complete teardown
-- path. Rayfield is mandatory for the hub UI; dependency failures show a
-- diagnostic-only panel and never a substitute feature interface.

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Protocol = __require("Shared.Protocol")
local Validation = __require("Shared.Validation")

local Runtime = __require("Client.Runtime")
local RayfieldLoader = __require("Client.RayfieldLoader")
local UIController = __require("Client.UIController")
local FallbackUI = __require("Client.FallbackUI")

local Boot = {}

local GUARD_NAME = "AgamtrashHubV1"

local function environment(): table?
    if type(getgenv) == "function" then
        local ok, value = pcall(getgenv)
        if ok and type(value) == "table" then
            return value
        end
    end
    -- Executors without getgenv can still share _G across runs, so the
    -- single-run guard must look there before creating a second interface.
    if type(_G) == "table" then
        return _G
    end
    return nil
end

local Handle = {}
Handle.__index = Handle

function Handle.new()
    return setmetatable({
        closed = false,
        runtime = nil,
        library = nil,
        ui = nil,
        fallback = nil,
    }, Handle)
end

function Handle:shutdown()
    if self.closed then
        return
    end
    self.closed = true

    if self.ui then
        pcall(self.ui.destroy, self.ui)
        self.ui = nil
    end
    if self.runtime then
        pcall(self.runtime.shutdown, self.runtime)
        self.runtime = nil
    end
    if self.library then
        pcall(self.library.Destroy, self.library)
        self.library = nil
    end
    if self.fallback then
        pcall(function()
            self.fallback:Destroy()
        end)
        self.fallback = nil
    end

    local env = environment()
    if env and env[GUARD_NAME] == self then
        env[GUARD_NAME] = nil
    end
end

local function showFallback(handle: any, code: string, detail: string?, capabilities: table)
    local ok, gui = pcall(FallbackUI.show, {
        code = code,
        detail = detail,
        capabilities = capabilities,
    })
    if ok then
        handle.fallback = gui
    end
    local suffix = detail and (": " .. tostring(detail)) or ""
    warn("[agamtrash.hub] UI unavailable (" .. tostring(code) .. ")" .. suffix)
end

function Boot.start(): (boolean, any)
    local player = Players.LocalPlayer
    if not player then
        return false, "NO_LOCAL_PLAYER"
    end

    local env = environment()
    local handle = Handle.new()
    if env then
        local previous = env[GUARD_NAME]
        if type(previous) == "table" and previous ~= handle and type(previous.shutdown) == "function" then
            pcall(previous.shutdown, previous)
        end
        env[GUARD_NAME] = handle
    end

    local capabilities = RayfieldLoader.capabilities()
    local clientInfo = {
        studio = capabilities.studio,
        loadstring = capabilities.loadstring,
        getObjects = capabilities.getObjects,
        httpGet = capabilities.httpGet,
        getgenv = capabilities.getgenv,
        rayfield = "not loaded",
    }

    if capabilities.studio then
        showFallback(handle, "STUDIO_RAYFIELD_UNAVAILABLE", nil, capabilities)
        return false, "STUDIO_RAYFIELD_UNAVAILABLE"
    end
    if not capabilities.loadstring then
        showFallback(handle, "EXECUTOR_LOADSTRING_MISSING", nil, capabilities)
        return false, "EXECUTOR_LOADSTRING_MISSING"
    end
    if not capabilities.getObjects then
        showFallback(handle, "EXECUTOR_GETOBJECTS_MISSING", nil, capabilities)
        return false, "EXECUTOR_GETOBJECTS_MISSING"
    end

    local library, code, detail = RayfieldLoader.load()
    if handle.closed then
        if library then
            pcall(library.Destroy, library)
        end
        return false, "CANCELLED"
    end
    if not library then
        showFallback(handle, code or "RAYFIELD_LOAD_FAILED", detail, capabilities)
        return false, code or "RAYFIELD_LOAD_FAILED"
    end
    handle.library = library
    clientInfo.rayfield = RayfieldLoader.describe()

    -- Runtime construction touches several modules and service lookups. A
    -- failure here must still tear Rayfield down and leave an actionable panel
    -- instead of an unhandled error with a dangling window.
    local runtimeOk, runtimeOrError = pcall(Runtime.new, { clientInfo = clientInfo })
    if not runtimeOk then
        pcall(library.Destroy, library)
        handle.library = nil
        -- The guard may have been shut down while Runtime.new yielded. Do not
        -- attach a fallback panel to a closed handle that nothing will clean up.
        if handle.closed then
            return false, "CANCELLED"
        end
        showFallback(handle, "RUNTIME_CONSTRUCTION_FAILED", "Runtime construction failed: " .. tostring(runtimeOrError), capabilities)
        return false, "RUNTIME_CONSTRUCTION_FAILED"
    end
    local runtime = runtimeOrError
    handle.runtime = runtime
    runtime:setClientInfo(clientInfo)

    -- The single-run guard can be shut down by a second Boot.start while a
    -- yielding Rayfield call is in progress. A runtime created after that
    -- shutdown is not owned by Handle:shutdown, so clean it up here.
    if handle.closed then
        pcall(runtime.shutdown, runtime)
        handle.runtime = nil
        pcall(library.Destroy, library)
        handle.library = nil
        return false, "CANCELLED"
    end

    local ui, uiError = UIController.new(runtime, library, {
        onUnload = function()
            handle:shutdown()
        end,
    })
    if handle.closed then
        if ui then
            pcall(ui.destroy, ui)
        end
        pcall(runtime.shutdown, runtime)
        handle.runtime = nil
        pcall(library.Destroy, library)
        handle.library = nil
        return false, "CANCELLED"
    end
    if not ui then
        local errorCode = "UI_CONSTRUCTION_FAILED"
        pcall(runtime.shutdown, runtime)
        handle.runtime = nil
        pcall(library.Destroy, library)
        handle.library = nil
        showFallback(handle, errorCode, "UI construction failed: " .. tostring(uiError), capabilities)
        return false, errorCode
    end

    handle.ui = ui
    runtime:attachUI(ui)
    runtime:getDiagnosticsLogger():info(string.format(
        "%s %s ready in %s scope. Rayfield %s.",
        Protocol.NAME,
        Protocol.VERSION,
        tostring((runtime:getEnvironment():getSnapshot() or {}).scope or "pending"),
        Protocol.RAYFIELD.Release
    ))

    local ok, err = pcall(runtime.initialize, runtime)
    if not ok then
        runtime:getDiagnosticsLogger():error("Runtime initialization failed: " .. Validation.truncate(err, 180))
        ui:notify("Initialization", "Some runtime services failed to initialize. Check the diagnostic log.")
    end
    ui:refreshStatus()
    return true, handle
end

return Boot
end

__modules["Client.CombatTest"] = function()
--!nonstrict
-- Combat Test Mode. Target discovery accepts only server-tagged, explicitly
-- approved development dummies. It never accepts player characters, target
-- names, positions or damage values from the UI.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")

local Protocol = __require("Shared.Protocol")
local Util = __require("Shared.Util")
local Validation = __require("Shared.Validation")

local CombatTest = {}
CombatTest.__index = CombatTest

local FATAL_CODES = {
    SERVER_COMPONENT_MISSING = true,
    REMOTE_MISSING = true,
    PLACE_NOT_AUTHORIZED = true,
    TESTER_NOT_AUTHORIZED = true,
    TESTER_ALLOWLIST_EMPTY = true,
    ENVIRONMENT_NOT_READY = true,
    FEATURE_DISABLED = true,
    FIXTURES_NOT_READY = true,
    SERVICE_UNAVAILABLE = true,
    CHARACTER_UNAVAILABLE = true,
}

function CombatTest.new(options: table)
    local self = setmetatable({}, CombatTest)
    self.scheduler = options.scheduler
    self.remote = options.remote
    self.environment = options.environment
    self.config = options.config
    self.logger = options.logger
    self.onAutoStopped = options.onAutoStopped
    self.running = false
    self.inFlight = false
    self.targetsSeen = 0
    self.attempts = 0
    self.successes = 0
    self.failures = 0
    self.lastResult = "None this session."
    self._taskName = "combat.attack"
    return self
end

local function characterRoot(): BasePart?
    local character = Players.LocalPlayer and Players.LocalPlayer.Character
    if not character then
        return nil
    end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if humanoid and humanoid.Health <= 0 then
        return nil
    end
    local root = character:FindFirstChild("HumanoidRootPart")
    return root and root:IsA("BasePart") and root or nil
end

function CombatTest:_setResult(text: string)
    self.lastResult = Validation.cleanText(text, 160) or "Unknown result."
end

function CombatTest:_apiAvailability(): (boolean, string?)
    local snapshot = self.environment:getSnapshot()
    if not self.remote:isAvailable() then
        return false, "REMOTE_MISSING"
    end
    if not snapshot then
        return false, "ENVIRONMENT_NOT_READY"
    end
    if not snapshot.authorized then
        return false, snapshot.code
    end
    if not snapshot.features.Combat then
        if not snapshot.fixturesReady then
            return false, "FIXTURES_NOT_READY"
        end
        return false, "FEATURE_DISABLED"
    end
    return true, nil
end

function CombatTest:_handleResult(response: table, automatic: boolean)
    self.inFlight = false
    if response.ok then
        self.successes += 1
        local data = response.data or {}
        self:_setResult(string.format(
            "Hit %s for %d · HP %s/%s%s",
            tostring(data.targetName or "approved target"),
            tonumber(data.damage) or 0,
            tostring(data.health or "?"),
            tostring(data.maxHealth or "?"),
            data.defeated and " · defeated" or ""
        ))
        return
    end

    self.failures += 1
    self:_setResult(Protocol.message(response.code))
    if automatic and FATAL_CODES[response.code] then
        if self.running then
            self:stop()
        end
        if self.onAutoStopped then
            pcall(self.onAutoStopped, response.code)
        end
    end
end

function CombatTest:_send(target: table, automatic: boolean): (boolean, string?)
    if self.inFlight then
        return false, "REMOTE_BUSY"
    end
    self.inFlight = true
    self.attempts += 1
    local requestId, errorCode = self.remote:request("Combat", {
        targetId = target.id,
    }, function(response)
        self:_handleResult(response, automatic)
    end)
    if not requestId then
        self.inFlight = false
        self:_setResult(Protocol.message(errorCode or "REMOTE_INVOKE_FAILED"))
        return false, errorCode or "REMOTE_INVOKE_FAILED"
    end
    return true, nil
end

function CombatTest:_scan(automatic: boolean, attackRange: number): (boolean, string?)
    local root = characterRoot()
    if not root then
        return false, "CHARACTER_UNAVAILABLE"
    end
    local available, code = self:_apiAvailability()
    if not available then
        return false, code
    end

    -- The scan range is the smaller of the requested client range and the
    -- server-advertised maximum. The server independently enforces its limit.
    local serverRange = self.environment:getLimit("combatRange", attackRange)
    local range = math.min(attackRange, serverRange)
    local list = {}
    for _, instance in ipairs(CollectionService:GetTagged(Protocol.TAGS.CombatTarget)) do
        if instance:IsA("Model")
            and instance:IsDescendantOf(workspace)
            and instance:GetAttribute(Protocol.ATTRIBUTES.Fixture) == true
            and instance:GetAttribute(Protocol.ATTRIBUTES.Approved) == true
            and not Util.isPlayerCharacter(instance)
        then
            local id = Validation.id(instance:GetAttribute(Protocol.ATTRIBUTES.Id), Protocol.IDS.MinLength, Protocol.IDS.MaxLength)
            local humanoid = instance:FindFirstChildOfClass("Humanoid")
            if id and humanoid and humanoid.Health > 0 then
                local distance = (root.Position - instance:GetPivot().Position).Magnitude
                if distance <= range then
                    table.insert(list, { instance = instance, id = id, distance = distance })
                end
            end
        end
    end
    table.sort(list, function(left, right)
        return left.distance < right.distance
    end)
    self.targetsSeen = #list
    if #list == 0 then
        self:_setResult("No approved target in range.")
        return false, "NO_TARGET"
    end
    return self:_send(list[1], automatic)
end

function CombatTest:_schedule()
    self.scheduler:cancel(self._taskName)
    local interval = self.config:getValue("Combat.Interval")
    self.scheduler:every(self._taskName, interval, function()
        local ok, err = pcall(function()
            self:_scan(true, self.config:getValue("Combat.Range"))
        end)
        if not ok then
            self.failures += 1
            self:_setResult(Validation.truncate(err, 160))
            self.logger:warn("Combat scan failed: " .. Validation.truncate(err, 160))
        end
    end, true)
end

function CombatTest:start(): (boolean, string?)
    if self.running then
        return true, nil
    end
    if not Players.LocalPlayer then
        return false, "CHARACTER_UNAVAILABLE"
    end
    local reason = self.environment:featureReason("Combat", true)
    if reason then
        return false, reason
    end
    if not self.remote:isAvailable() then
        return false, self.remote:getReason() or "REMOTE_MISSING"
    end
    self.running = true
    self.inFlight = false
    self:_schedule()
    return true, nil
end

function CombatTest:stop()
    self.running = false
    self.scheduler:cancel(self._taskName)
end

function CombatTest:attackNearest(): (boolean, string?)
    local reason = self.environment:featureReason("Combat", true)
    if reason then
        return false, reason
    end
    if self.inFlight then
        return false, "REMOTE_BUSY"
    end
    return self:_scan(false, self.config:getValue("Combat.Range"))
end

function CombatTest:applyConfig()
    if self.running then
        self:_schedule()
    end
end

function CombatTest:isRunning(): boolean
    return self.running
end

function CombatTest:getStatusText(): string
    local state = self.running and "running" or "stopped"
    return string.format("%s · %d approved in range · %d attempts · %d hits", state, self.targetsSeen, self.attempts, self.successes)
end

function CombatTest:getDetailText(): string
    return string.format("Last result: %s\nFailures: %d", self.lastResult, self.failures)
end

return CombatTest
end

__modules["Client.EnvironmentClient"] = function()
--!nonstrict
-- Environment handshake and feature gate. Feature modules call featureReason
-- before starting and on every state transition. The server still re-checks
-- authorization for each request; this is only the client-side UX gate.

local Protocol = __require("Shared.Protocol")
local Validation = __require("Shared.Validation")

local EnvironmentClient = {}
EnvironmentClient.__index = EnvironmentClient

local FIXTURE_FEATURES = {
    Money = true,
    ATM = true,
    Combat = true,
    TargetVisualization = true,
    ItemVisualization = true,
}

function EnvironmentClient.new(options: table)
    local self = setmetatable({}, EnvironmentClient)
    self.remote = options.remote
    self.logger = options.logger
    self.onChanged = options.onChanged
    self.snapshot = nil
    self.loading = false
    self.lastErrorCode = nil
    self.lastErrorDetail = nil
    self.refreshes = 0
    return self
end

local function statusCode(snapshot: table?): string?
    if not snapshot then
        return nil
    end
    return snapshot.code
end

function EnvironmentClient:refresh(callback: ((boolean, table?, string?) -> ())?)
    if self.loading then
        if callback then
            callback(false, self.snapshot, "ENVIRONMENT_NOT_READY")
        end
        return
    end
    self.loading = true
    self.refreshes += 1

    -- This runs in a separate thread so the UI can render while the server
    -- handshake is in flight.
    task.spawn(function()
        local ok, snapshot, code, detail = self.remote:fetchEnvironment()
        self.loading = false
        if ok then
            local wasCode = statusCode(self.snapshot)
            self.snapshot = snapshot
            self.lastErrorCode = nil
            self.lastErrorDetail = nil
            if snapshot.authorized then
                self.logger:info("Environment handshake accepted (" .. snapshot.scope .. " scope).")
            else
                self.logger:warn("Environment locked: " .. snapshot.message)
            end
            if callback then
                pcall(callback, true, snapshot, nil)
            end
            if self.onChanged then
                pcall(self.onChanged, snapshot, wasCode)
            end
        else
            self.snapshot = nil
            self.lastErrorCode = code or "SERVER_COMPONENT_MISSING"
            self.lastErrorDetail = detail
            self.logger:warn("Environment unavailable: " .. Protocol.message(self.lastErrorCode))
            if callback then
                pcall(callback, false, nil, self.lastErrorCode)
            end
            if self.onChanged then
                pcall(self.onChanged, nil, self.lastErrorCode)
            end
        end
    end)
end

function EnvironmentClient:getSnapshot(): table?
    return self.snapshot
end

function EnvironmentClient:getStatusCode(): string?
    if self.lastErrorCode then
        return self.lastErrorCode
    end
    if self.snapshot then
        return self.snapshot.code
    end
    return "ENVIRONMENT_NOT_READY"
end

function EnvironmentClient:isAuthorized(): boolean
    return self.snapshot ~= nil and self.snapshot.authorized == true
end

function EnvironmentClient:getLimit(name: string, fallback: number): number
    if self.snapshot and self.snapshot.limits and type(self.snapshot.limits[name]) == "number" then
        return self.snapshot.limits[name]
    end
    return fallback
end

function EnvironmentClient:featureReason(feature: string, requireFixtures: boolean?): string?
    if not Protocol.isFeature(feature) then
        return "SERVICE_UNAVAILABLE"
    end
    if self.loading and not self.snapshot then
        return "ENVIRONMENT_NOT_READY"
    end
    if not self.snapshot then
        return self.lastErrorCode or "ENVIRONMENT_NOT_READY"
    end
    if not self.snapshot.authorized then
        return self.snapshot.code
    end
    if not self.snapshot.features[feature] then
        if requireFixtures ~= false and FIXTURE_FEATURES[feature] and not self.snapshot.fixturesReady then
            return "FIXTURES_NOT_READY"
        end
        return "FEATURE_DISABLED"
    end
    return nil
end

function EnvironmentClient:getStatusLine(): string
    if self.loading and not self.snapshot then
        return "Contacting authorized server component..."
    end
    if not self.snapshot then
        return "Locked: " .. Protocol.message(self.lastErrorCode or "ENVIRONMENT_NOT_READY")
    end
    local s = self.snapshot
    if not s.authorized then
        return "Locked (" .. s.scope .. "): " .. s.message
    end
    return string.format(
        "Authorized · %s scope · server %s · protocol %d · fixtures %s",
        s.scope,
        s.serverVersion,
        s.protocol,
        s.fixturesReady and "ready" or "missing"
    )
end

function EnvironmentClient:getDiagnosticsLine(): string
    if not self.snapshot then
        local detail = self.lastErrorDetail
        if detail then
            return (self.lastErrorCode or "INVALID_ENVIRONMENT") .. " · " .. Validation.truncate(detail, 160)
        end
        return self.lastErrorCode or "ENVIRONMENT_NOT_READY"
    end
    return string.format(
        "code=%s · scope=%s · version=%s · received=%s",
        self.snapshot.code,
        self.snapshot.scope,
        self.snapshot.serverVersion,
        string.format("%.1fs ago", math.max(0, os.clock() - self.snapshot.receivedAt))
    )
end

return EnvironmentClient
end

__modules["Client.FallbackUI"] = function()
--!nonstrict
-- Dependency-error panel. This is deliberately NOT a hub replacement: it has no
-- feature controls and cannot start modules. It exists so a failed Rayfield load
-- is visible and actionable instead of failing silently.

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Protocol = __require("Shared.Protocol")
local Validation = __require("Shared.Validation")

local FallbackUI = {}

local GUI_NAME = "AgamtrashFallback"
local CHARCOAL = Color3.fromRGB(17, 21, 28)
local PANEL = Color3.fromRGB(24, 30, 39)
local STROKE = Color3.fromRGB(48, 62, 79)
local ACCENT = Color3.fromRGB(46, 128, 220)
local TEXT = Color3.fromRGB(232, 238, 246)
local MUTED = Color3.fromRGB(158, 171, 188)
local WARN = Color3.fromRGB(255, 190, 92)

local function label(parent: Instance, name: string, position: UDim2, size: UDim2, font: Enum.Font, textSize: number, color: Color3): TextLabel
    local value = Instance.new("TextLabel")
    value.Name = name
    value.BackgroundTransparency = 1
    value.Position = position
    value.Size = size
    value.Font = font
    value.TextSize = textSize
    value.TextColor3 = color
    value.TextXAlignment = Enum.TextXAlignment.Left
    value.TextYAlignment = Enum.TextYAlignment.Top
    value.TextWrapped = true
    value.Parent = parent
    return value
end

function FallbackUI.show(options: any?): any?
    local settings = options or {}
    local player = Players.LocalPlayer
    local playerGui = player and player:FindFirstChildOfClass("PlayerGui")
    if not playerGui then
        return nil
    end

    local existing = playerGui:FindFirstChild(GUI_NAME)
    if existing then
        existing:Destroy()
    end

    local code = Validation.cleanText(settings.code, 64) or "RAYFIELD_LOAD_FAILED"
    local detail = Validation.cleanText(settings.detail, 260) or "No additional detail was provided."
    local message = Protocol.message(code)
    local caps = settings.capabilities or {}

    local gui = Instance.new("ScreenGui")
    gui.Name = GUI_NAME
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    gui.DisplayOrder = 100
    gui.Parent = playerGui

    local backdrop = Instance.new("Frame")
    backdrop.Name = "Backdrop"
    backdrop.Size = UDim2.fromScale(1, 1)
    backdrop.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    backdrop.BackgroundTransparency = 0.45
    backdrop.BorderSizePixel = 0
    backdrop.Parent = gui

    local panel = Instance.new("Frame")
    panel.Name = "DiagnosticPanel"
    panel.AnchorPoint = Vector2.new(0.5, 0.5)
    panel.Position = UDim2.fromScale(0.5, 0.5)
    panel.Size = UDim2.fromOffset(540, 380)
    panel.BackgroundColor3 = PANEL
    panel.BorderSizePixel = 0
    panel.Active = true
    panel.Parent = gui

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 8)
    corner.Parent = panel

    local outline = Instance.new("UIStroke")
    outline.Color = STROKE
    outline.Thickness = 1
    outline.Parent = panel

    local accent = Instance.new("Frame")
    accent.Name = "Accent"
    accent.Size = UDim2.new(1, 0, 0, 3)
    accent.BackgroundColor3 = ACCENT
    accent.BorderSizePixel = 0
    accent.Parent = panel
    local accentCorner = Instance.new("UICorner")
    accentCorner.CornerRadius = UDim.new(0, 8)
    accentCorner.Parent = accent

    local title = label(panel, "Title", UDim2.fromOffset(22, 18), UDim2.new(1, -44, 0, 30), Enum.Font.GothamBold, 22, TEXT)
    title.Text = Protocol.NAME .. " · UI dependency check"

    local subtitle = label(panel, "Subtitle", UDim2.fromOffset(22, 49), UDim2.new(1, -44, 0, 18), Enum.Font.Gotham, 13, MUTED)
    subtitle.Text = Protocol.TARGET_GAME.Subtitle .. " · Rayfield is required. No substitute hub UI was created."

    local codeLabel = label(panel, "Code", UDim2.fromOffset(22, 82), UDim2.new(1, -44, 0, 20), Enum.Font.Code, 14, WARN)
    codeLabel.Text = code

    local messageLabel = label(panel, "Message", UDim2.fromOffset(22, 106), UDim2.new(1, -44, 0, 44), Enum.Font.Gotham, 13, TEXT)
    messageLabel.Text = message

    local detailLabel = label(panel, "Detail", UDim2.fromOffset(22, 152), UDim2.new(1, -44, 0, 34), Enum.Font.Gotham, 12, MUTED)
    detailLabel.Text = detail

    local capsule = Instance.new("Frame")
    capsule.Name = "Capabilities"
    capsule.Position = UDim2.fromOffset(22, 194)
    capsule.Size = UDim2.new(1, -44, 0, 92)
    capsule.BackgroundColor3 = CHARCOAL
    capsule.BorderSizePixel = 0
    capsule.Parent = panel
    local capsuleCorner = Instance.new("UICorner")
    capsuleCorner.CornerRadius = UDim.new(0, 6)
    capsuleCorner.Parent = capsule
    local capsuleStroke = Instance.new("UIStroke")
    capsuleStroke.Color = STROKE
    capsuleStroke.Thickness = 1
    capsuleStroke.Parent = capsule

    local capabilityTitle = label(capsule, "CapabilityTitle", UDim2.fromOffset(12, 8), UDim2.new(1, -24, 0, 16), Enum.Font.GothamBold, 12, MUTED)
    capabilityTitle.Text = "ENVIRONMENT CAPABILITIES"

    local capabilityText = label(capsule, "CapabilityText", UDim2.fromOffset(12, 26), UDim2.new(1, -24, 0, 58), Enum.Font.Code, 12, TEXT)
    capabilityText.Text = table.concat({
        "Studio: " .. tostring(caps.studio == true),
        "loadstring: " .. tostring(caps.loadstring == true) .. "   game:GetObjects: " .. tostring(caps.getObjects == true),
        "game:HttpGet: " .. tostring(caps.httpGet == true) .. "   getgenv: " .. tostring(caps.getgenv == true),
    }, "\n")

    local instructions = label(panel, "Instructions", UDim2.fromOffset(22, 298), UDim2.new(1, -44, 0, 46), Enum.Font.Gotham, 12, MUTED)
    instructions.Text = "Run the standalone build in an authorized Xeno session, or install the Rojo project in an experience you own. Vanilla Studio cannot load the executor Rayfield interface asset."

    local dismiss = Instance.new("TextButton")
    dismiss.Name = "Dismiss"
    dismiss.AnchorPoint = Vector2.new(1, 1)
    dismiss.Position = UDim2.new(1, -20, 1, -18)
    dismiss.Size = UDim2.fromOffset(110, 30)
    dismiss.BackgroundColor3 = ACCENT
    dismiss.BorderSizePixel = 0
    dismiss.AutoButtonColor = false
    dismiss.Font = Enum.Font.GothamBold
    dismiss.TextSize = 13
    dismiss.TextColor3 = Color3.fromRGB(248, 251, 255)
    dismiss.Text = "Dismiss"
    dismiss.Parent = panel
    local dismissCorner = Instance.new("UICorner")
    dismissCorner.CornerRadius = UDim.new(0, 5)
    dismissCorner.Parent = dismiss
    dismiss.MouseButton1Click:Connect(function()
        gui:Destroy()
    end)

    local version = label(panel, "Version", UDim2.fromOffset(22, 352), UDim2.new(1, -170, 0, 18), Enum.Font.Gotham, 11, MUTED)
    version.Text = Protocol.NAME .. " " .. Protocol.VERSION .. " · diagnostic only"

    return gui
end

return FallbackUI
end

__modules["Client.ItemESP"] = function()
--!nonstrict
-- Item ESP uses only CollectionService tags and metadata attributes placed there
-- by the authorized server fixtures. It never invents categories or item names.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")

local Protocol = __require("Shared.Protocol")
local Util = __require("Shared.Util")
local Validation = __require("Shared.Validation")

local ItemESP = {}
ItemESP.__index = ItemESP

local GUI_NAME = "AgamtrashItemVisuals"

function ItemESP.new(options: table)
    local self = setmetatable({}, ItemESP)
    self.scheduler = options.scheduler
    self.config = options.config
    self.environment = options.environment
    self.logger = options.logger
    self.onCategoriesChanged = options.onCategoriesChanged
    self.state = "stopped"
    self.entries = {}
    self.folder = nil
    self.filter = "All"
    self.categories = { "All" }
    self.visibleCount = 0
    self.taggedCount = 0
    self._style = nil
    self._taskName = "item.esp"
    return self
end

local function localRoot(): BasePart?
    local character = Players.LocalPlayer and Players.LocalPlayer.Character
    if not character then
        return nil
    end
    local root = character:FindFirstChild("HumanoidRootPart")
    return root and root:IsA("BasePart") and root or nil
end

local function itemMetadata(instance: Instance): table?
    if not instance:IsA("BasePart")
        or not instance:IsDescendantOf(workspace)
        or instance:GetAttribute(Protocol.ATTRIBUTES.Fixture) ~= true
    then
        return nil
    end
    local id = Validation.id(instance:GetAttribute(Protocol.ATTRIBUTES.Id), Protocol.IDS.MinLength, Protocol.IDS.MaxLength)
    local name = Validation.cleanText(instance:GetAttribute(Protocol.ATTRIBUTES.DisplayName), 60)
    local category = Validation.cleanText(instance:GetAttribute(Protocol.ATTRIBUTES.Category), 40)
    if not id or not name or not category then
        return nil
    end
    return { id = id, name = name, category = category }
end

function ItemESP:_refreshCategories()
    local set = { All = true }
    for _, instance in ipairs(CollectionService:GetTagged(Protocol.TAGS.Item)) do
        local meta = itemMetadata(instance)
        if meta then
            set[meta.category] = true
        end
    end
    local list = {}
    for category in pairs(set) do
        table.insert(list, category)
    end
    table.sort(list, function(left, right)
        if left == "All" then
            return true
        end
        if right == "All" then
            return false
        end
        return left < right
    end)
    local changed = #list ~= #self.categories
    if not changed then
        for index, value in ipairs(list) do
            if self.categories[index] ~= value then
                changed = true
                break
            end
        end
    end
    self.categories = list
    if self.filter ~= "All" and not set[self.filter] then
        self.filter = "All"
    end
    if changed and self.onCategoriesChanged then
        pcall(self.onCategoriesChanged, list, self.filter)
    end
end

function ItemESP:getCategories(): { string }
    local copy = {}
    for index, category in ipairs(self.categories) do
        copy[index] = category
    end
    return copy
end

function ItemESP:getFilter(): string
    return self.filter
end

function ItemESP:setCategory(category: string)
    if type(category) ~= "string" then
        return
    end
    if category == "All" or table.find(self.categories, category) then
        self.filter = category
        if self.state == "running" then
            self:refresh()
        end
    end
end

function ItemESP:_destroyEntry(entry: table)
    if entry.billboard then
        entry.billboard:Destroy()
    end
    if entry.highlight then
        entry.highlight:Destroy()
    end
end

function ItemESP:_ensureFolder()
    local playerGui = Players.LocalPlayer and Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
    if not playerGui then
        return nil
    end
    local existing = playerGui:FindFirstChild(GUI_NAME)
    if existing then
        existing:Destroy()
    end
    local folder = Instance.new("ScreenGui")
    folder.Name = GUI_NAME
    folder.ResetOnSpawn = false
    folder.IgnoreGuiInset = true
    folder.DisplayOrder = 49
    folder.Parent = playerGui
    self.folder = folder
    return folder
end

function ItemESP:_createEntry(part: BasePart, meta: table): table
    local billboard = Instance.new("BillboardGui")
    billboard.Name = "AgamtrashItem"
    billboard.Adornee = part
    billboard.AlwaysOnTop = true
    billboard.MaxDistance = self.config:getValue("Items.VisualRange")
    billboard.Size = UDim2.fromOffset(210, 46)
    billboard.StudsOffsetWorldSpace = Vector3.new(0, 1.9, 0)
    billboard.LightInfluence = 0

    local background = Instance.new("Frame")
    background.Size = UDim2.fromScale(1, 1)
    background.BackgroundColor3 = Color3.fromRGB(16, 21, 28)
    background.BackgroundTransparency = 0.2
    background.BorderSizePixel = 0
    background.Parent = billboard

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 6)
    corner.Parent = background

    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(58, 120, 80)
    stroke.Transparency = 0.25
    stroke.Thickness = 1
    stroke.Parent = background

    local title = Instance.new("TextLabel")
    title.Name = "ItemName"
    title.Size = UDim2.new(1, -14, 0, 23)
    title.Position = UDim2.fromOffset(7, 3)
    title.BackgroundTransparency = 1
    title.Font = Enum.Font.GothamBold
    title.TextSize = 13
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.TextColor3 = Color3.fromRGB(236, 245, 240)
    title.Text = meta.name
    title.Parent = background

    local detail = Instance.new("TextLabel")
    detail.Name = "ItemDetail"
    detail.Size = UDim2.new(1, -14, 0, 17)
    detail.Position = UDim2.fromOffset(7, 25)
    detail.BackgroundTransparency = 1
    detail.Font = Enum.Font.Gotham
    detail.TextSize = 11
    detail.TextXAlignment = Enum.TextXAlignment.Left
    detail.TextColor3 = Color3.fromRGB(134, 218, 166)
    detail.Text = meta.category
    detail.Parent = background

    billboard.Parent = self.folder

    local entry = { billboard = billboard, title = title, detail = detail, highlight = nil }
    if self.config:getValue("Items.Style") == "Billboard + Highlight" then
        local highlight = Instance.new("Highlight")
        highlight.Name = "AgamtrashItemHighlight"
        highlight.Adornee = part
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.FillColor = Color3.fromRGB(73, 209, 126)
        highlight.FillTransparency = 0.82
        highlight.OutlineColor = Color3.fromRGB(115, 241, 166)
        highlight.OutlineTransparency = 0.2
        highlight.Parent = part
        entry.highlight = highlight
    end
    return entry
end

function ItemESP:_updateEntry(entry: table, meta: table, distance: number)
    if self.config:getValue("Items.ShowName") == false then
        entry.title.Text = ""
    else
        entry.title.Text = meta.name
    end
    local pieces = { meta.category }
    if self.config:getValue("Items.ShowDistance") then
        table.insert(pieces, Util.formatDistance(distance))
    end
    entry.detail.Text = table.concat(pieces, "  ·  ")
end

function ItemESP:refresh()
    if self.state ~= "running" then
        return
    end
    self:_refreshCategories()

    local root = localRoot()
    if not root then
        for _, entry in pairs(self.entries) do
            self:_destroyEntry(entry)
        end
        self.entries = {}
        self.visibleCount = 0
        return
    end

    local style = self.config:getValue("Items.Style")
    if style ~= self._style then
        for _, entry in pairs(self.entries) do
            self:_destroyEntry(entry)
        end
        self.entries = {}
        self._style = style
    end

    local range = self.config:getValue("Items.VisualRange")
    local seen = {}
    local visible = 0
    local tagged = 0

    for _, instance in ipairs(CollectionService:GetTagged(Protocol.TAGS.Item)) do
        local meta = itemMetadata(instance)
        if meta then
            tagged += 1
            if self.filter == "All" or meta.category == self.filter then
                local distance = (root.Position - instance.Position).Magnitude
                if distance <= range then
                    visible += 1
                    seen[instance] = true
                    local entry = self.entries[instance]
                    if not entry then
                        entry = self:_createEntry(instance, meta)
                        self.entries[instance] = entry
                    else
                        entry.title.Text = meta.name
                    end
                    entry.billboard.MaxDistance = range
                    self:_updateEntry(entry, meta, distance)
                end
            end
        end
    end

    for instance, entry in pairs(self.entries) do
        if not seen[instance] or not instance.Parent then
            self:_destroyEntry(entry)
            self.entries[instance] = nil
        end
    end
    self.visibleCount = visible
    self.taggedCount = tagged
end

function ItemESP:start(): (boolean, string?)
    if self.state == "running" then
        return true, nil
    end
    if not Players.LocalPlayer then
        return false, "CHARACTER_UNAVAILABLE"
    end
    local reason = self.environment:featureReason("ItemVisualization", true)
    if reason then
        return false, reason
    end
    if not self:_ensureFolder() then
        return false, "INVALID_ENVIRONMENT"
    end
    self.state = "running"
    self._style = nil
    self.entries = {}
    self:_refreshCategories()
    self.scheduler:every(self._taskName, 1.0, function()
        local ok, err = pcall(function()
            self:refresh()
        end)
        if not ok then
            self.logger:warn("Item ESP refresh failed: " .. Validation.truncate(err, 160))
        end
    end, true)
    return true, nil
end

function ItemESP:stop()
    self.state = "stopped"
    self.scheduler:cancel(self._taskName)
    for _, entry in pairs(self.entries) do
        self:_destroyEntry(entry)
    end
    self.entries = {}
    self.visibleCount = 0
    if self.folder then
        self.folder:Destroy()
        self.folder = nil
    end
end

function ItemESP:rebuild()
    if self.state ~= "running" then
        return
    end
    for _, entry in pairs(self.entries) do
        self:_destroyEntry(entry)
    end
    self.entries = {}
    self._style = nil
    self:refresh()
end

function ItemESP:isRunning(): boolean
    return self.state == "running"
end

function ItemESP:getStatusText(): string
    if self.state ~= "running" then
        return "stopped"
    end
    return string.format("running · %d shown / %d tagged · filter %s", self.visibleCount, self.taggedCount, self.filter)
end

return ItemESP
end

__modules["Client.MoneyCollector"] = function()
--!nonstrict
-- Auto Collect Money for authorized development fixtures. The client scans
-- real tagged parts, reports diagnostics and asks the server to collect by ID.
-- It never edits money attributes, balances or game currency locally.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")

local Protocol = __require("Shared.Protocol")
local Validation = __require("Shared.Validation")

local MoneyCollector = {}
MoneyCollector.__index = MoneyCollector

local FATAL_CODES = {
    SERVER_COMPONENT_MISSING = true,
    REMOTE_MISSING = true,
    PLACE_NOT_AUTHORIZED = true,
    TESTER_NOT_AUTHORIZED = true,
    TESTER_ALLOWLIST_EMPTY = true,
    ENVIRONMENT_NOT_READY = true,
    ENVIRONMENT_RATE_LIMITED = true,
    FEATURE_DISABLED = true,
    FIXTURES_NOT_READY = true,
    SERVICE_UNAVAILABLE = true,
}

function MoneyCollector.new(options: table)
    local self = setmetatable({}, MoneyCollector)
    self.scheduler = options.scheduler
    self.remote = options.remote
    self.environment = options.environment
    self.config = options.config
    self.diagnostics = options.diagnostics
    self.logger = options.logger
    self.onAutoStopped = options.onAutoStopped
    self.running = false
    self.inFlight = false
    self._taskName = "money.collect"
    self._blockedReason = nil
    self.diagnostics:setRadius(self.config:getValue("Money.Radius"))
    return self
end

local function characterRoot(): BasePart?
    local character = Players.LocalPlayer and Players.LocalPlayer.Character
    if not character then
        return nil
    end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if humanoid and humanoid.Health <= 0 then
        return nil
    end
    local root = character:FindFirstChild("HumanoidRootPart")
    return root and root:IsA("BasePart") and root or nil
end

local function collectibleMetadata(instance: Instance): table?
    if not instance:IsA("BasePart")
        or not instance:IsDescendantOf(workspace)
        or instance:GetAttribute(Protocol.ATTRIBUTES.Fixture) ~= true
        or instance:GetAttribute(Protocol.ATTRIBUTES.Available) ~= true
    then
        return nil
    end
    local id = Validation.id(instance:GetAttribute(Protocol.ATTRIBUTES.Id), Protocol.IDS.MinLength, Protocol.IDS.MaxLength)
    local value = instance:GetAttribute(Protocol.ATTRIBUTES.Value)
    if not id or not Validation.isFiniteNumber(value) or value <= 0 then
        return nil
    end
    return {
        instance = instance,
        id = id,
        value = value,
    }
end

function MoneyCollector:_apiAvailability()
    local snapshot = self.environment:getSnapshot()
    if not self.remote:isAvailable() then
        self.diagnostics:setApiAvailable(false, "Server remote unavailable.")
        return false, "REMOTE_MISSING"
    end
    if not snapshot then
        self.diagnostics:setApiAvailable(false, "Environment handshake unavailable.")
        return false, "ENVIRONMENT_NOT_READY"
    end
    if not snapshot.authorized then
        self.diagnostics:setApiAvailable(false, "Server environment is locked.")
        return false, snapshot.code
    end
    if not snapshot.features.Money then
        if not snapshot.fixturesReady then
            self.diagnostics:setApiAvailable(false, "Fixtures are not ready on this server.")
            return false, "FIXTURES_NOT_READY"
        end
        self.diagnostics:setApiAvailable(false, "Money feature is disabled by the server.")
        return false, "FEATURE_DISABLED"
    end
    self.diagnostics:setApiAvailable(true, "CollectionService and server remote ready.")
    return true, nil
end

function MoneyCollector:_eligible(root: BasePart): { table }
    local radius = self.config:getValue("Money.Radius")
    local list = {}
    for _, instance in ipairs(CollectionService:GetTagged(Protocol.TAGS.Money)) do
        local meta = collectibleMetadata(instance)
        if meta then
            local distance = (root.Position - instance.Position).Magnitude
            if distance <= radius then
                table.insert(list, {
                    instance = instance,
                    id = meta.id,
                    value = meta.value,
                    distance = distance,
                })
            end
        end
    end
    table.sort(list, function(left, right)
        return left.distance < right.distance
    end)
    self.diagnostics:setEligibleCount(#list)
    return list
end

function MoneyCollector:_handleResult(response: table, automatic: boolean)
    self.inFlight = false
    if not self.running and automatic then
        return
    end
    if response.ok then
        local data = response.data or {}
        self.diagnostics:recordSuccess({
            value = data.value,
            balance = data.balance,
            itemName = data.itemName,
        })
        self._blockedReason = nil
        if self.running then
            self.diagnostics:setModuleState("running")
        end
    else
        local message = Protocol.message(response.code)
        self.diagnostics:recordError(message)
        if FATAL_CODES[response.code] then
            self.diagnostics:setApiAvailable(false, Protocol.message(response.code))
            if self.running then
                self:stop()
                self.diagnostics:setModuleState("unavailable")
                if self.onAutoStopped then
                    pcall(self.onAutoStopped, response.code)
                end
            end
        end
    end
end

function MoneyCollector:_send(entry: table, automatic: boolean): (boolean, string?)
    if self.inFlight then
        return false, "REMOTE_BUSY"
    end
    self.inFlight = true
    self.diagnostics:recordRequest()
    local requestId, errorCode = self.remote:request("Money", {
        collectibleId = entry.id,
    }, function(response)
        self:_handleResult(response, automatic)
    end)
    if not requestId then
        self.inFlight = false
        self.diagnostics:recordError(Protocol.message(errorCode or "REMOTE_INVOKE_FAILED"))
        return false, errorCode or "REMOTE_INVOKE_FAILED"
    end
    return true, nil
end

function MoneyCollector:_scan(automatic: boolean): (boolean, string?)
    local root = characterRoot()
    if not root then
        self.diagnostics:setModuleState(automatic and "paused" or "stopped")
        return false, "CHARACTER_UNAVAILABLE"
    end

    local available, code = self:_apiAvailability()
    if not available then
        self.diagnostics:setModuleState("unavailable")
        if self._blockedReason ~= code then
            self._blockedReason = code
            self.diagnostics:recordError(Protocol.message(code))
        end
        return false, code
    end
    self._blockedReason = nil

    local list = self:_eligible(root)
    if #list == 0 then
        if automatic then
            self.diagnostics:setModuleState("running")
        end
        return false, "NO_TARGET"
    end
    if automatic then
        self.diagnostics:setModuleState("running")
    end
    return self:_send(list[1], automatic)
end

function MoneyCollector:_schedule()
    self.scheduler:cancel(self._taskName)
    local interval = self.config:getValue("Money.Interval")
    self.scheduler:every(self._taskName, interval, function()
        local ok, err = pcall(function()
            self:_scan(true)
        end)
        if not ok then
            self.diagnostics:recordError(Validation.truncate(err, 180))
            self.logger:warn("Money scan failed: " .. Validation.truncate(err, 160))
        end
    end, true)
end

function MoneyCollector:start(): (boolean, string?)
    if self.running then
        return true, nil
    end
    if not Players.LocalPlayer then
        return false, "CHARACTER_UNAVAILABLE"
    end
    local reason = self.environment:featureReason("Money", true)
    if reason then
        self.diagnostics:setModuleState("unavailable")
        return false, reason
    end
    if not self.remote:isAvailable() then
        return false, self.remote:getReason() or "REMOTE_MISSING"
    end

    self.running = true
    self.inFlight = false
    self.diagnostics:setModuleState("running")
    self.diagnostics:setRadius(self.config:getValue("Money.Radius"))
    self:_schedule()
    return true, nil
end

function MoneyCollector:stop()
    self.running = false
    self.scheduler:cancel(self._taskName)
    self.diagnostics:setModuleState("stopped")
    self.diagnostics:setEligibleCount(0)
end

function MoneyCollector:collectNearest(): (boolean, string?)
    local reason = self.environment:featureReason("Money", true)
    if reason then
        self.diagnostics:recordError(Protocol.message(reason))
        return false, reason
    end
    if self.inFlight then
        return false, "REMOTE_BUSY"
    end
    return self:_scan(false)
end

function MoneyCollector:applyConfig()
    self.diagnostics:setRadius(self.config:getValue("Money.Radius"))
    if self.running then
        self:_schedule()
    end
end

function MoneyCollector:isRunning(): boolean
    return self.running
end

function MoneyCollector:getDiagnostics(): table
    return self.diagnostics:snapshot()
end

function MoneyCollector:formatDiagnostics(): string
    return self.diagnostics:format()
end

return MoneyCollector
end

__modules["Client.NoclipDebug"] = function()
--!nonstrict
-- Client controller for the server-authoritative noclip debug session. This
-- module never writes CanCollide, CollisionGroup or character physics locally.
-- It sends a request and polls status so the UI notices server-side expiry,
-- death restoration or character changes.

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Protocol = __require("Shared.Protocol")

local NoclipDebug = {}
NoclipDebug.__index = NoclipDebug

-- These responses mean the request did not reach a confirmed server decision.
-- While a session is active, keep the previous server-known state and let the
-- poll or the server timeout resolve it instead of falsely showing "inactive".
local UNCERTAIN_CODES = {
    RATE_LIMITED = true,
    REMOTE_BUSY = true,
    RESPONSE_TIMEOUT = true,
}

function NoclipDebug.new(options: table)
    local self = setmetatable({}, NoclipDebug)
    self.scheduler = options.scheduler
    self.remote = options.remote
    self.environment = options.environment
    self.config = options.config
    self.onStateChanged = options.onStateChanged
    self.logger = options.logger
    self.active = false
    self.requesting = false
    self.parts = 0
    self.expiresAt = nil
    self.lastMessage = "Inactive."
    self._pollTask = "noclip.status"
    self._destroyed = false
    return self
end

function NoclipDebug:_notify()
    if self._destroyed then
        return
    end
    if self.onStateChanged then
        pcall(self.onStateChanged, self:getStatus())
    end
end

function NoclipDebug:_stopPolling()
    self.scheduler:cancel(self._pollTask)
end

function NoclipDebug:_applyResponse(response: table): boolean
    local data = response.data or {}
    local wasActive = self.active
    self.requesting = false

    if response.ok and data.active == true then
        self.active = true
        self.parts = tonumber(data.parts) or self.parts
        local expiresIn = tonumber(data.expiresIn)
        if expiresIn then
            self.expiresAt = os.clock() + math.max(0, expiresIn)
        end
        self.lastMessage = string.format(
            "Active · %d part(s) · %s remaining",
            self.parts,
            string.format("%.0fs", math.max(0, (self.expiresAt or os.clock()) - os.clock()))
        )
        self:_startPolling()
    elseif self.active and not response.ok and UNCERTAIN_CODES[response.code] then
        self.requesting = false
        self.lastMessage = Protocol.message(response.code) .. " · server state not confirmed"
        self:_notify()
        return self.active
    else
        self.active = false
        self.parts = 0
        self.expiresAt = nil
        if response.ok then
            self.lastMessage = wasActive and Protocol.message("NOCLIP_EXPIRED") or "Inactive."
        else
            self.lastMessage = Protocol.message(response.code)
        end
        self:_stopPolling()
    end
    self:_notify()
    return self.active
end

function NoclipDebug:_startPolling()
    if not self.active then
        return
    end
    self.scheduler:cancel(self._pollTask)
    self.scheduler:every(self._pollTask, 5.0, function()
        if not self.active then
            self:_stopPolling()
            return
        end
        if self.requesting then
            return
        end
        self.requesting = true
        local requestId, errorCode = self.remote:request("Noclip", { action = "status" }, function(response)
            self:_applyResponse(response)
        end)
        if not requestId then
            self.requesting = false
            self.lastMessage = Protocol.message(errorCode or "REMOTE_INVOKE_FAILED")
            self.active = false
            self.expiresAt = nil
            self:_stopPolling()
            self:_notify()
        end
    end, false)
end

function NoclipDebug:_requestAction(action: string, callback: ((table) -> ())?): (boolean, string?)
    local reason = self.environment:featureReason("Noclip", false)
    if reason then
        return false, reason
    end
    if not self.remote:isAvailable() then
        return false, self.remote:getReason() or "REMOTE_MISSING"
    end
    if self.requesting then
        return false, "REMOTE_BUSY"
    end

    self.requesting = true
    local requestId, errorCode = self.remote:request("Noclip", { action = action }, function(response)
        self:_applyResponse(response)
        if action == "disable" and response.ok then
            self.lastMessage = "Inactive · original collision restored."
            self:_notify()
        end
        if callback then
            pcall(callback, response)
        end
    end)
    if not requestId then
        self.requesting = false
        self.lastMessage = Protocol.message(errorCode or "REMOTE_INVOKE_FAILED")
        self:_notify()
        return false, errorCode or "REMOTE_INVOKE_FAILED"
    end
    return true, nil
end

function NoclipDebug:enable(callback: ((table) -> ())?)
    if self.active then
        return true, nil
    end
    return self:_requestAction("enable", callback)
end

function NoclipDebug:disable(callback: ((table) -> ())?)
    return self:_requestAction("disable", callback)
end

function NoclipDebug:getStatus(): table
    return {
        active = self.active,
        requesting = self.requesting,
        parts = self.parts,
        expiresIn = self.expiresAt and math.max(0, self.expiresAt - os.clock()) or nil,
        message = self.lastMessage,
    }
end

function NoclipDebug:getStatusText(): string
    if self.requesting and not self.active then
        return "requesting server decision..."
    end
    if self.active then
        return string.format(
            "ACTIVE · %d part(s) · %s remaining · server-owned",
            self.parts,
            string.format("%.0fs", math.max(0, (self.expiresAt or os.clock()) - os.clock()))
        )
    end
    return "inactive · " .. self.lastMessage
end

function NoclipDebug:isActive(): boolean
    return self.active
end

function NoclipDebug:shutdown()
    self._destroyed = true
    self:_stopPolling()
    if self.active and self.remote:isAvailable() then
        -- Fire-and-forget restore request. The server also has its own timeout,
        -- so even an interrupted client cannot leave the state active forever.
        self.remote:request("Noclip", { action = "disable" }, function() end, 3)
    end
    self.active = false
    self.requesting = false
end

return NoclipDebug
end

__modules["Client.RayfieldLoader"] = function()
--!nonstrict
-- Loads the reviewed Rayfield build only. The standalone bundle embeds the
-- vetted source; the pinned URL is a fallback for development environments that
-- expose game:HttpGet. No UI is substituted when Rayfield cannot load.
--
-- The source is checked by byte count and reviewed markers at runtime. The
-- build scripts separately verify its SHA-256 against Protocol.RAYFIELD.
-- Analytics and Rayfield's update prompts are opted out before execution.
-- Rayfield secure/anti-detection mode is deliberately never enabled.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local Protocol = __require("Shared.Protocol")
local Validation = __require("Shared.Validation")

local RayfieldLoader = {}

RayfieldLoader.SOURCE_GLOBAL = "AgamtrashRayfieldSourceV1"

local MAX_DOWNLOAD_BYTES = Protocol.RAYFIELD.SourceBytes + 65536

local REQUIRED_MARKERS = {
    "Rayfield Interface Suite",
    "local InterfaceBuild = 'UU2NX'",
    'local Release = "Build 1.753"',
    "local RayfieldAssetId =",
    "function RayfieldLibrary:CreateWindow",
    "function RayfieldLibrary:Notify",
    "return RayfieldLibrary",
}

local REQUIRED_LIBRARY_API = {
    "CreateWindow",
    "Notify",
    "Destroy",
    "SetVisibility",
    "IsVisible",
}

local function environment(): table?
    if type(getgenv) ~= "function" then
        return nil
    end
    local ok, value = pcall(getgenv)
    if ok and type(value) == "table" then
        return value
    end
    return nil
end

function RayfieldLoader.capabilities(): table
    local caps = {
        studio = false,
        loadstring = type(loadstring) == "function",
        getObjects = type(game.GetObjects) == "function",
        httpGet = type(game.HttpGet) == "function",
        getgenv = type(getgenv) == "function",
    }
    local ok, isStudio = pcall(function()
        return RunService:IsStudio()
    end)
    caps.studio = ok and isStudio == true
    return caps
end

local function validateSource(source: any): (boolean, string?, string?)
    if type(source) ~= "string" or source == "" then
        return false, "RAYFIELD_FETCH_FAILED", "The Rayfield source was empty."
    end
    if #source > MAX_DOWNLOAD_BYTES then
        return false, "RAYFIELD_TOO_LARGE", string.format(
            "Source was %d bytes; the review guard is %d bytes.",
            #source,
            MAX_DOWNLOAD_BYTES
        )
    end
    if #source ~= Protocol.RAYFIELD.SourceBytes then
        return false, "UNEXPECTED_BUILD", string.format(
            "Source was %d bytes; the reviewed build is %d bytes.",
            #source,
            Protocol.RAYFIELD.SourceBytes
        )
    end
    for _, marker in ipairs(REQUIRED_MARKERS) do
        if not string.find(source, marker, 1, true) then
            return false, "UNEXPECTED_BUILD", "A reviewed Rayfield marker is missing."
        end
    end
    return true, nil, nil
end

local function readEmbedded(options: table): string?
    if type(options.source) == "string" then
        return options.source
    end
    local env = environment()
    if env and type(env[RayfieldLoader.SOURCE_GLOBAL]) == "string" then
        return env[RayfieldLoader.SOURCE_GLOBAL]
    end
    if type(_G) == "table" and type(_G[RayfieldLoader.SOURCE_GLOBAL]) == "string" then
        return _G[RayfieldLoader.SOURCE_GLOBAL]
    end
    if type(getfenv) == "function" then
        local ok, globalEnv = pcall(getfenv, 0)
        if ok and type(globalEnv) == "table" and type(globalEnv[RayfieldLoader.SOURCE_GLOBAL]) == "string" then
            return globalEnv[RayfieldLoader.SOURCE_GLOBAL]
        end
    end
    return nil
end

local function downloadSource(): (string?, string?, string?)
    if type(game.HttpGet) ~= "function" then
        return nil, "EXECUTOR_HTTP_MISSING", nil
    end
    local ok, result = pcall(function()
        return game:HttpGet(Protocol.RAYFIELD.SourceUrl)
    end)
    if not ok then
        return nil, "RAYFIELD_FETCH_FAILED", Validation.truncate(result, 200)
    end
    if type(result) ~= "string" or result == "" then
        return nil, "RAYFIELD_FETCH_FAILED", "The pinned URL returned no source."
    end
    if #result > MAX_DOWNLOAD_BYTES then
        return nil, "RAYFIELD_TOO_LARGE", string.format("Downloaded %d bytes.", #result)
    end
    return result, nil, nil
end

local function optOut(env: table?)
    local function apply(target: any)
        if type(target) ~= "table" then
            return
        end
        pcall(function()
            target.DISABLE_RAYFIELD_REQUESTS = true
            target.RAYFIELD_ANALYTICS = false
        end)
    end
    apply(env)
    -- `_G` is also a possible Rayfield environment, particularly on executors
    -- that do not expose getgenv. Set both so analytics stay disabled.
    apply(_G)
end

local function executeSource(source: string): (any?, string?, string?)
    if type(loadstring) ~= "function" then
        return nil, "EXECUTOR_LOADSTRING_MISSING", nil
    end
    local chunk, compileError = loadstring(source, "@agamtrash-rayfield")
    if type(chunk) ~= "function" then
        return nil, "RAYFIELD_LOAD_FAILED", Validation.truncate(compileError, 220)
    end
    local ok, library = pcall(chunk)
    if not ok then
        return nil, "RAYFIELD_LOAD_FAILED", Validation.truncate(library, 220)
    end
    if type(library) ~= "table" then
        return nil, "RAYFIELD_API_MISSING", "Rayfield did not return its library table."
    end
    for _, name in ipairs(REQUIRED_LIBRARY_API) do
        if type(library[name]) ~= "function" then
            return nil, "RAYFIELD_API_MISSING", "Missing Rayfield API: " .. name
        end
    end
    return library, nil, nil
end

-- Returns (RayfieldLibrary?, errorCode?, detail?). The caller owns the library
-- lifecycle and must call :Destroy() when the hub unloads.
function RayfieldLoader.load(options: any?): (any?, string?, string?)
    local settings = options or {}
    local caps = RayfieldLoader.capabilities()

    if caps.studio and settings.allowStudio ~= true then
        return nil, "STUDIO_RAYFIELD_UNAVAILABLE",
            "Vanilla Roblox Studio cannot execute the executor Rayfield interface asset. No replacement UI was created."
    end
    if not caps.loadstring then
        return nil, "EXECUTOR_LOADSTRING_MISSING", "The executor does not expose loadstring."
    end
    if not caps.getObjects then
        return nil, "EXECUTOR_GETOBJECTS_MISSING", "The executor does not expose game:GetObjects."
    end

    local env = environment()
    optOut(env)

    local source = readEmbedded(settings)
    if source then
        local valid, code, detail = validateSource(source)
        if not valid then
            return nil, code, detail
        end
    else
        if settings.allowDownload == false then
            return nil, "RAYFIELD_FETCH_FAILED", "No embedded source is available and download is disabled."
        end
        local downloaded, code, detail = downloadSource()
        if not downloaded then
            return nil, code, detail
        end
        source = downloaded
        local valid, validationCode, validationDetail = validateSource(source)
        if not valid then
            return nil, validationCode, validationDetail
        end
    end

    return executeSource(source)
end

function RayfieldLoader.describe(): string
    local caps = RayfieldLoader.capabilities()
    return string.format(
        "%s · source %d bytes · loadstring=%s · GetObjects=%s · HttpGet=%s · Studio=%s",
        Protocol.RAYFIELD.Flavor,
        Protocol.RAYFIELD.SourceBytes,
        tostring(caps.loadstring),
        tostring(caps.getObjects),
        tostring(caps.httpGet),
        tostring(caps.studio)
    )
end

return RayfieldLoader
end

__modules["Client.RemoteClient"] = function()
--!nonstrict
-- Client transport. This module owns remote discovery, request correlation,
-- response validation and local timeouts. Feature modules only receive validated
-- plain responses; they never invoke an Instance remote directly.

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Protocol = __require("Shared.Protocol")
local EnvironmentSchema = __require("Shared.EnvironmentSchema")
local Util = __require("Shared.Util")
local Validation = __require("Shared.Validation")

local RemoteClient = {}
RemoteClient.__index = RemoteClient

local FEATURE_REMOTE_NAMES = {
    Money = Protocol.REMOTES.Money,
    ATM = Protocol.REMOTES.ATM,
    Combat = Protocol.REMOTES.Combat,
    Noclip = Protocol.REMOTES.Noclip,
}

local function validResponse(raw: any): (boolean, table?, string?)
    if not Validation.safeTable(raw) then
        return false, nil, "Response was not a plain table."
    end
    if type(raw.ok) ~= "boolean" then
        return false, nil, "Response was missing its status."
    end
    if type(raw.feature) ~= "string" or not Protocol.isFeature(raw.feature) then
        return false, nil, "Response feature was invalid."
    end
    local requestId = Validation.id(raw.requestId, Protocol.IDS.MinLength, Protocol.IDS.MaxLength)
    if not requestId then
        return false, nil, "Response request ID was invalid."
    end
    if type(raw.code) ~= "string" or raw.code == "" then
        return false, nil, "Response code was invalid."
    end
    local code = Validation.cleanText(raw.code, 64)
    if not code or code == "" then
        return false, nil, "Response code was invalid."
    end
    if raw.ok ~= (code == "OK") then
        return false, nil, "Response status and code disagreed."
    end
    local message = Validation.cleanText(raw.message, 240) or Protocol.message(code)
    local data = nil
    if raw.data ~= nil then
        if type(raw.data) ~= "table" then
            return false, nil, "Response data was not a table."
        end
        data = raw.data
    end
    return true, {
        ok = raw.ok,
        feature = raw.feature,
        requestId = requestId,
        code = code,
        message = message,
        data = data,
    }, nil
end

function RemoteClient.new(options: any?)
    local settings = options or {}
    local self = setmetatable({}, RemoteClient)
    self.logger = settings.logger
    self.pending = {}
    self.featureRemotes = {}
    self.environmentRemote = nil
    self.respondRemote = nil
    self.respondConnection = nil
    self.available = false
    self.reason = "SERVER_COMPONENT_MISSING"
    return self
end

function RemoteClient:probe(waitSeconds: number?): boolean
    if self.available then
        return true
    end

    local folder = ReplicatedStorage:FindFirstChild(Protocol.REMOTES_FOLDER)
    if not folder and waitSeconds and waitSeconds > 0 then
        folder = ReplicatedStorage:WaitForChild(Protocol.REMOTES_FOLDER, waitSeconds)
    end
    if not folder or not folder:IsA("Folder") then
        self.reason = "SERVER_COMPONENT_MISSING"
        return false
    end

    local environment = folder:FindFirstChild(Protocol.REMOTES.Environment)
    local respond = folder:FindFirstChild(Protocol.REMOTES.Respond)
    if not environment or not environment:IsA("RemoteFunction") then
        self.reason = "REMOTE_MISSING"
        return false
    end
    if not respond or not respond:IsA("RemoteEvent") then
        self.reason = "REMOTE_MISSING"
        return false
    end

    local featureRemotes = {}
    for feature, remoteName in pairs(FEATURE_REMOTE_NAMES) do
        local remote = folder:FindFirstChild(remoteName)
        if not remote or not remote:IsA("RemoteEvent") then
            self.reason = "REMOTE_MISSING"
            return false
        end
        featureRemotes[feature] = remote
    end

    self.environmentRemote = environment
    self.respondRemote = respond
    self.featureRemotes = featureRemotes
    self.available = true
    self.reason = nil

    if self.respondConnection then
        self.respondConnection:Disconnect()
    end
    self.respondConnection = respond.OnClientEvent:Connect(function(response)
        self:_receive(response)
    end)
    return true
end

function RemoteClient:isAvailable(): boolean
    return self.available
end

function RemoteClient:getReason(): string?
    return self.reason
end

function RemoteClient:_receive(raw: any)
    local valid, response, reason = validResponse(raw)
    if not valid then
        if self.logger then
            self.logger:warn("Ignored malformed server response: " .. tostring(reason))
        end
        return
    end

    local pending = self.pending[response.requestId]
    if not pending then
        -- A late response after local timeout is still useful to diagnostics but
        -- has no active callback to protect.
        return
    end
    if pending.feature ~= response.feature then
        if self.logger then
            self.logger:warn("Ignored a response whose feature did not match its request.")
        end
        return
    end
    self.pending[response.requestId] = nil

    local ok, err = pcall(pending.callback, response)
    if not ok and self.logger then
        self.logger:warn("A request callback failed: " .. Validation.truncate(err, 160))
    end
end

function RemoteClient:_timeout(requestId: string)
    local pending = self.pending[requestId]
    if not pending then
        return
    end
    self.pending[requestId] = nil
    local response = {
        ok = false,
        feature = pending.feature,
        requestId = requestId,
        code = "RESPONSE_TIMEOUT",
        message = Protocol.message("RESPONSE_TIMEOUT"),
        data = nil,
    }
    local ok, err = pcall(pending.callback, response)
    if not ok and self.logger then
        self.logger:warn("A timeout callback failed: " .. Validation.truncate(err, 160))
    end
end

-- Sends a request and invokes callback exactly once: on a validated server
-- response or on a local timeout. Returns (requestId?, errorCode?).
function RemoteClient:request(feature: string, payload: table, callback: (table) -> (), timeoutSeconds: number?): (string?, string?)
    if not self:probe() then
        return nil, self.reason or "SERVER_COMPONENT_MISSING"
    end
    local remote = self.featureRemotes[feature]
    if not remote then
        return nil, "REMOTE_MISSING"
    end
    if type(callback) ~= "function" then
        return nil, "INVALID_RESPONSE"
    end

    local requestId = Util.requestId(feature)
    self.pending[requestId] = {
        feature = feature,
        callback = callback,
    }

    local ok = pcall(function()
        remote:FireServer({
            requestId = requestId,
            payload = payload,
        })
    end)
    if not ok then
        self.pending[requestId] = nil
        return nil, "REMOTE_INVOKE_FAILED"
    end

    local timeout = timeoutSeconds or Protocol.TIMEOUTS.requestSeconds
    task.delay(timeout, function()
        self:_timeout(requestId)
    end)
    return requestId, nil
end

function RemoteClient:fetchEnvironment(): (boolean, table?, string?, string?)
    if not self:probe() then
        return false, nil, self.reason or "SERVER_COMPONENT_MISSING", nil
    end
    local remote = self.environmentRemote
    if not remote then
        return false, nil, "REMOTE_MISSING", nil
    end

    local ok, raw = pcall(function()
        return remote:InvokeServer()
    end)
    if not ok then
        if self.logger then
            self.logger:warn("Environment remote invocation failed: " .. Validation.truncate(raw, 160))
        end
        return false, nil, "REMOTE_INVOKE_FAILED", nil
    end

    local valid, snapshot, reason = EnvironmentSchema.validate(raw)
    if not valid then
        return false, nil, "INVALID_ENVIRONMENT", reason
    end
    return true, snapshot, nil, nil
end

function RemoteClient:destroy()
    if self.respondConnection then
        pcall(function()
            self.respondConnection:Disconnect()
        end)
        self.respondConnection = nil
    end
    self.pending = {}
    self.available = false
end

return RemoteClient
end

__modules["Client.Runtime"] = function()
--!nonstrict
-- Client composition root. Feature modules, transport, configuration and the
-- scheduler are wired here. The UI talks to this runtime only, never directly
-- to remotes or Roblox collision state.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local Players = game:GetService("Players")

local Protocol = __require("Shared.Protocol")
local ConfigManager = __require("Shared.ConfigManager")
local Diagnostics = __require("Shared.Diagnostics")
local MoneyDiagnostics = __require("Shared.MoneyDiagnostics")
local Scheduler = __require("Shared.Scheduler")
local Util = __require("Shared.Util")
local Validation = __require("Shared.Validation")

local RemoteClient = __require("Client.RemoteClient")
local EnvironmentClient = __require("Client.EnvironmentClient")
local MoneyCollector = __require("Client.MoneyCollector")
local CombatTest = __require("Client.CombatTest")
local TargetVisualizer = __require("Client.TargetVisualizer")
local ItemESP = __require("Client.ItemESP")
local ATMInteractionTest = __require("Client.ATMInteractionTest")
local NoclipDebug = __require("Client.NoclipDebug")

local Runtime = {}
Runtime.__index = Runtime

-- Feature starts can fail because the whole environment is locked. Repeating the
-- same paragraph for every toggle is noisy, so these codes collapse into one
-- short notice per lock state; Settings > Environment keeps the full detail.
local LOCK_CODES = {
    SERVER_COMPONENT_MISSING = true,
    REMOTE_MISSING = true,
    ENVIRONMENT_NOT_READY = true,
    SERVER_NOT_READY = true,
    PLACE_NOT_AUTHORIZED = true,
    TESTER_NOT_AUTHORIZED = true,
    TESTER_ALLOWLIST_EMPTY = true,
    NOT_AUTHORIZED = true,
    FEATURE_DISABLED = true,
    FIXTURES_NOT_READY = true,
    ENVIRONMENT_RATE_LIMITED = true,
}

function Runtime.new(options: any?)
    local settings = options or {}
    local self = setmetatable({}, Runtime)
    self._destroyed = false
    self._ui = nil
    self._clientInfo = settings.clientInfo or {}
    self._environmentWasAuthorized = false
    self._lastLockNotice = nil

    self.diagnostics = Diagnostics.new({
        maxEntries = 240,
        debug = false,
        sink = function(level, text)
            local prefix = "[agamtrash.hub] "
            if level == "error" or level == "warn" then
                warn(prefix .. text)
            elseif level ~= "debug" then
                print(prefix .. text)
            end
        end,
    })
    self.config = ConfigManager.new(self.diagnostics)
    self.moneyDiagnostics = MoneyDiagnostics.new({
        radius = self.config:getValue("Money.Radius"),
    })
    self.scheduler = Scheduler.new({
        onError = function(name, err)
            self.diagnostics:error("Scheduled task '" .. tostring(name) .. "' failed: " .. Validation.truncate(err, 160))
        end,
    })
    self.remote = RemoteClient.new({ logger = self.diagnostics })
    self.environment = EnvironmentClient.new({
        remote = self.remote,
        logger = self.diagnostics,
        onChanged = function(snapshot, previousCode)
            self:_onEnvironmentChanged(snapshot, previousCode)
        end,
    })

    self.money = MoneyCollector.new({
        scheduler = self.scheduler,
        remote = self.remote,
        environment = self.environment,
        config = self.config,
        diagnostics = self.moneyDiagnostics,
        logger = self.diagnostics,
        onAutoStopped = function(code)
            self:_onAutoStopped("Money", code)
        end,
    })
    self.combat = CombatTest.new({
        scheduler = self.scheduler,
        remote = self.remote,
        environment = self.environment,
        config = self.config,
        logger = self.diagnostics,
        onAutoStopped = function(code)
            self:_onAutoStopped("Combat", code)
        end,
    })
    self.targets = TargetVisualizer.new({
        scheduler = self.scheduler,
        config = self.config,
        environment = self.environment,
        logger = self.diagnostics,
    })
    self.items = ItemESP.new({
        scheduler = self.scheduler,
        config = self.config,
        environment = self.environment,
        logger = self.diagnostics,
        onCategoriesChanged = function(categories)
            if self._ui and self._ui.onItemCategories then
                pcall(self._ui.onItemCategories, self._ui, categories, self.items:getFilter())
            end
        end,
    })
    self.atm = ATMInteractionTest.new({
        scheduler = self.scheduler,
        remote = self.remote,
        environment = self.environment,
        config = self.config,
        logger = self.diagnostics,
        onAutoStopped = function(code)
            self:_onAutoStopped("ATM", code)
        end,
    })
    self.noclip = NoclipDebug.new({
        scheduler = self.scheduler,
        remote = self.remote,
        environment = self.environment,
        config = self.config,
        logger = self.diagnostics,
        onStateChanged = function(status)
            if self._ui and self._ui.onNoclipState then
                pcall(self._ui.onNoclipState, self._ui, status)
            end
        end,
    })

    self._configConnection = self.config:subscribe(function(path, _value)
        self:_onConfigChanged(path)
    end)
    self._heartbeat = RunService.Heartbeat:Connect(function()
        if self._destroyed then
            return
        end
        self.scheduler:update(os.clock())
    end)
    return self
end

function Runtime:initialize()
    -- Give replicated remotes a short window to arrive; the UI is already
    -- created at this point and stays responsive while this yields.
    self.remote:probe(2)
    self.environment:refresh()
    -- Retry the handshake periodically so a late server component is noticed
    -- without restarting the hub. Responses are cheap and rate-limited server-side.
    self.scheduler:every("environment.refresh", 30, function()
        self.environment:refresh()
    end, false)
    self.diagnostics:info("Runtime initialized. Target-game integration is not implemented.")
end

function Runtime:attachUI(ui: any)
    self._ui = ui
end

function Runtime:setClientInfo(info: table)
    for key, value in pairs(info or {}) do
        self._clientInfo[key] = value
    end
end

function Runtime:getClientInfo(): table
    return self._clientInfo
end

function Runtime:_onConfigChanged(path: string)
    if path == "*" then
        self.money:applyConfig()
        self.combat:applyConfig()
        self.atm:applyConfig()
        if self.targets:isRunning() then
            self.targets:rebuild()
        end
        if self.items:isRunning() then
            self.items:rebuild()
        end
        self.diagnostics:setDebug(self.config:getValue("Settings.DebugLogging") == true)
        return
    end

    if path == "Settings.DebugLogging" then
        self.diagnostics:setDebug(self.config:getValue("Settings.DebugLogging") == true)
    elseif path == "Money.Radius" or path == "Money.Interval" then
        self.money:applyConfig()
    elseif path == "Combat.Range" or path == "Combat.Interval" then
        self.combat:applyConfig()
    elseif string.sub(path, 1, 6) == "Combat" then
        if self.targets:isRunning() then
            self.targets:rebuild()
        end
    elseif string.sub(path, 1, 5) == "Items" then
        if self.items:isRunning() then
            self.items:rebuild()
        end
    elseif path == "ATM.Interval" or path == "ATM.Mode" then
        self.atm:applyConfig()
    end
end

function Runtime:_onEnvironmentChanged(snapshot: table?, previousCode: string?)
    if snapshot then
        self.diagnostics:debug("Environment changed: " .. snapshot.code)
        if not snapshot.authorized and self._environmentWasAuthorized then
            self:_stopGameplayModules("server authorization changed")
            self:_notifyLocked(snapshot.code)
        end
        self._environmentWasAuthorized = snapshot.authorized
        if snapshot.authorized then
            self._lastLockNotice = nil
        end
    else
        if self._environmentWasAuthorized then
            self:_stopGameplayModules("server handshake lost")
            self:_notifyLocked(previousCode or "SERVER_COMPONENT_MISSING")
        end
        self._environmentWasAuthorized = false
    end
    if self._ui and self._ui.refreshStatus then
        pcall(self._ui.refreshStatus, self._ui)
    end
end

function Runtime:_notify(title: string, content: string)
    if self._ui and self._ui.notify then
        pcall(self._ui.notify, self._ui, title, content)
    else
        self.diagnostics:info(title .. ": " .. tostring(content))
    end
end

function Runtime:_notifyLocked(code: string?)
    local key = code or "SERVER_COMPONENT_MISSING"
    if self._lastLockNotice == key then
        return
    end
    self._lastLockNotice = key

    if key == "SERVER_COMPONENT_MISSING" or key == "REMOTE_MISSING" then
        self:_notify("Features locked", "Server component not found. Features stay locked. Details: Settings > Environment.")
    elseif key == "ENVIRONMENT_NOT_READY" or key == "SERVER_NOT_READY" then
        self:_notify("Features locked", "The environment handshake is not ready yet. Try again in a moment.")
    else
        self:_notify("Features locked", Protocol.message(key) .. " Details: Settings > Environment.")
    end
end

function Runtime:_notifyFailure(title: string, code: string?)
    if code and LOCK_CODES[code] then
        self:_notifyLocked(code)
    else
        self:_notify(title, Protocol.message(code))
    end
end

function Runtime:_onAutoStopped(feature: string, code: string)
    self.diagnostics:warn(Protocol.FEATURE_LABELS[feature] .. " stopped: " .. tostring(code))
    self:_notifyFailure(Protocol.FEATURE_LABELS[feature] or feature, code)
    if self._ui and self._ui.onAutoStopped then
        pcall(self._ui.onAutoStopped, self._ui, feature, code)
    end
end

function Runtime:_stopGameplayModules(reason: string)
    self.money:stop()
    self.combat:stop()
    self.atm:stop()
    self.targets:stop()
    self.items:stop()
    if self.noclip:isActive() then
        self.noclip:disable()
    end
    self.diagnostics:warn("Stopped gameplay modules: " .. reason)
end

function Runtime:stopAll(reason: string?): boolean
    self:_stopGameplayModules(reason or "manual stop")
    self:_notify("Modules", "All gameplay modules were stopped. Configuration was kept.")
    return true
end

function Runtime:getEnvironment(): EnvironmentClient
    return self.environment
end

function Runtime:getConfig(): ConfigManager
    return self.config
end

function Runtime:getDiagnosticsLogger(): Diagnostics
    return self.diagnostics
end

function Runtime:getItemCategories(): { string }
    return self.items:getCategories()
end

function Runtime:getItemCategory(): string
    return self.items:getFilter()
end

function Runtime:setItemCategory(category: string)
    self.items:setCategory(category)
end

function Runtime:refreshEnvironment(callback: ((boolean, table?, string?) -> ())?)
    self.remote:probe(2)
    self.environment:refresh(callback)
end

function Runtime:setConfig(path: string, value: any): (boolean, string?)
    local ok, reason = self.config:set(path, value)
    if not ok then
        self:_notify("Configuration", Protocol.message("INVALID_CONFIG") .. " " .. tostring(reason))
    end
    return ok, reason
end

function Runtime:setAutoMoney(enabled: boolean): (boolean, string?)
    if enabled then
        local ok, reason = self.money:start()
        if not ok then
            self:_notifyFailure("Money", reason)
        end
        return ok, reason
    end
    self.money:stop()
    return true, nil
end

function Runtime:collectNearest(): (boolean, string?)
    local ok, reason = self.money:collectNearest()
    if not ok and reason ~= "NO_TARGET" and reason ~= "REMOTE_BUSY" then
        self:_notifyFailure("Money", reason)
    elseif reason == "NO_TARGET" then
        self:_notify("Money", Protocol.message("NO_TARGET"))
    end
    return ok, reason
end

function Runtime:setCombat(enabled: boolean): (boolean, string?)
    if enabled then
        local ok, reason = self.combat:start()
        if not ok then
            self:_notifyFailure("Combat", reason)
        end
        return ok, reason
    end
    self.combat:stop()
    return true, nil
end

function Runtime:attackNearest(): (boolean, string?)
    local ok, reason = self.combat:attackNearest()
    if not ok and reason ~= "NO_TARGET" and reason ~= "REMOTE_BUSY" then
        self:_notifyFailure("Combat", reason)
    elseif reason == "NO_TARGET" then
        self:_notify("Combat", Protocol.message("NO_TARGET"))
    end
    return ok, reason
end

function Runtime:setTargetVisualization(enabled: boolean): (boolean, string?)
    if enabled then
        local ok, reason = self.targets:start()
        if not ok then
            self:_notifyFailure("Target Visualization", reason)
        end
        return ok, reason
    end
    self.targets:stop()
    return true, nil
end

function Runtime:setItemESP(enabled: boolean): (boolean, string?)
    if enabled then
        local ok, reason = self.items:start()
        if not ok then
            self:_notifyFailure("Item ESP", reason)
        end
        return ok, reason
    end
    self.items:stop()
    return true, nil
end

function Runtime:setATM(enabled: boolean): (boolean, string?)
    if enabled then
        local ok, reason = self.atm:start()
        if not ok then
            self:_notifyFailure("ATM Test", reason)
        end
        return ok, reason
    end
    self.atm:stop()
    return true, nil
end

function Runtime:atmInteractOnce(): (boolean, string?)
    local ok, reason = self.atm:interactOnce()
    if not ok and reason ~= "NO_TARGET" and reason ~= "REMOTE_BUSY" then
        self:_notifyFailure("ATM Test", reason)
    elseif reason == "NO_TARGET" then
        self:_notify("ATM Test", Protocol.message("NO_TARGET"))
    end
    return ok, reason
end

function Runtime:setNoclip(enabled: boolean): (boolean, string?)
    local callback = function(response: table)
        if response.ok then
            self:_notify("Noclip Debug", enabled and "Server enabled the debug session. Collision will be restored automatically." or "Server restored the original collision settings.")
        else
            self:_notifyFailure("Noclip Debug", response.code)
        end
        if self._ui and self._ui.onNoclipState then
            pcall(self._ui.onNoclipState, self._ui, self.noclip:getStatus())
        end
    end

    if enabled then
        local ok, reason = self.noclip:enable(callback)
        if not ok then
            self:_notifyFailure("Noclip Debug", reason)
            if self._ui and self._ui.onNoclipState then
                pcall(self._ui.onNoclipState, self._ui, self.noclip:getStatus())
            end
        end
        return ok, reason
    end

    local status = self.noclip:getStatus()
    if not status.active and not status.requesting then
        return true, nil
    end
    local ok, reason = self.noclip:disable(callback)
    if not ok then
        self:_notifyFailure("Noclip Debug", reason)
    end
    return ok, reason
end

function Runtime:resetSession()
    self:_stopGameplayModules("configuration reset")
    self.config:reset()
    self.items:setCategory("All")
    self.moneyDiagnostics:setRadius(self.config:getValue("Money.Radius"))
    self.diagnostics:info("Session configuration reset to defaults.")
    if self._ui and self._ui.onConfigReset then
        pcall(self._ui.onConfigReset, self._ui)
    end
    return true
end

function Runtime:getModuleStatuses(): { { key: string, label: string, status: string } }
    return {
        { key = "Money", label = Protocol.FEATURE_LABELS.Money, status = self.moneyDiagnostics:getModuleState() .. string.format(" · %d eligible", self.moneyDiagnostics:snapshot().eligibleCount) },
        { key = "Combat", label = Protocol.FEATURE_LABELS.Combat, status = self.combat:getStatusText() },
        { key = "TargetVisualization", label = Protocol.FEATURE_LABELS.TargetVisualization, status = self.targets:getStatusText() },
        { key = "ItemVisualization", label = Protocol.FEATURE_LABELS.ItemVisualization, status = self.items:getStatusText() },
        { key = "ATM", label = Protocol.FEATURE_LABELS.ATM, status = self.atm:getStatusText() },
        { key = "Noclip", label = Protocol.FEATURE_LABELS.Noclip, status = self.noclip:getStatusText() },
    }
end

function Runtime:getFeatureStates(): table
    local noclipStatus = self.noclip:getStatus()
    return {
        Money = self.money:isRunning(),
        Combat = self.combat:isRunning(),
        TargetVisualization = self.targets:isRunning(),
        ItemVisualization = self.items:isRunning(),
        ATM = self.atm:isRunning(),
        Noclip = noclipStatus.active == true,
        NoclipRequesting = noclipStatus.requesting == true,
    }
end

function Runtime:getStatusSnapshot(): table
    return {
        environment = self.environment:getStatusLine(),
        environmentDetail = self.environment:getDiagnosticsLine(),
        money = self.moneyDiagnostics:format(),
        combat = self.combat:getStatusText(),
        combatDetail = self.combat:getDetailText(),
        targets = self.targets:getStatusText(),
        items = self.items:getStatusText(),
        atm = self.atm:getStatusText(),
        atmDetail = self.atm:getDetailText(),
        noclip = self.noclip:getStatusText(),
        modules = self:formatModuleStatuses(),
    }
end

function Runtime:getMoneyDiagnostics(): table
    return self.money:getDiagnostics()
end

function Runtime:formatMoneyDiagnostics(): string
    return self.money:formatDiagnostics()
end

function Runtime:formatModuleStatuses(): string
    local lines = {}
    for _, entry in ipairs(self:getModuleStatuses()) do
        table.insert(lines, entry.label .. ": " .. entry.status)
    end
    return table.concat(lines, "\n")
end

function Runtime:buildCompatibilityReport(): string
    local info = self._clientInfo
    local snapshot = self.environment:getSnapshot()
    local lines = {
        "agamtrash.hub " .. Protocol.VERSION .. " · protocol " .. tostring(Protocol.PROTOCOL),
        "Environment: " .. self.environment:getStatusLine(),
        "Server remote: " .. (self.remote:isAvailable() and "available" or ("unavailable (" .. tostring(self.remote:getReason()) .. ")")) ,
        "Rayfield: " .. tostring(info.rayfield or "not loaded"),
        "Studio: " .. tostring(info.studio == true),
        "Executor loadstring: " .. (info.loadstring and "available" or "missing"),
        "Executor game:GetObjects: " .. (info.getObjects and "available" or "missing"),
        "Executor game:HttpGet: " .. (info.httpGet and "available" or "missing"),
        "Executor getgenv: " .. (info.getgenv and "available" or "missing"),
        "Scheduler tasks: " .. tostring(self.scheduler:count()),
        "UI: " .. (self._ui and "attached" or "not attached"),
        "Third-party game integration: not implemented (by design)",
    }
    return table.concat(lines, "\n")
end

function Runtime:runCompatibilityCheck(): string
    local report = self:buildCompatibilityReport()
    self.diagnostics:info("Compatibility check completed.")
    self:_notify("Compatibility Check", report)
    return report
end

function Runtime:getRecentDiagnostics(): string
    return self.diagnostics:format(10)
end

function Runtime:logStatusSnapshot()
    self.diagnostics:debug(self:formatModuleStatuses())
end

function Runtime:addTask(name: string, interval: number, callback: (number) -> (), immediate: boolean?): boolean
    return self.scheduler:every(name, interval, callback, immediate)
end

function Runtime:cancelTask(name: string)
    self.scheduler:cancel(name)
end

function Runtime:shutdown()
    if self._destroyed then
        return
    end
    self._destroyed = true
    self.scheduler:cancel("environment.refresh")
    self.money:stop()
    self.combat:stop()
    self.atm:stop()
    self.targets:stop()
    self.items:stop()
    self.noclip:shutdown()
    self.scheduler:clear()
    self.remote:destroy()
    if self._configConnection then
        self._configConnection()
        self._configConnection = nil
    end
    if self._heartbeat then
        pcall(function()
            self._heartbeat:Disconnect()
        end)
        self._heartbeat = nil
    end
    self.diagnostics:info("Runtime stopped and client resources cleaned up.")
end

return Runtime
end

__modules["Client.TargetVisualizer"] = function()
--!nonstrict
-- Approved-target visualization. It only reads CollectionService tags and
-- server-owned attributes. Player characters are never visualized or offered as
-- combat targets.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")

local Protocol = __require("Shared.Protocol")
local Util = __require("Shared.Util")
local Validation = __require("Shared.Validation")

local TargetVisualizer = {}
TargetVisualizer.__index = TargetVisualizer

local GUI_NAME = "AgamtrashTargetVisuals"

function TargetVisualizer.new(options: table)
    local self = setmetatable({}, TargetVisualizer)
    self.scheduler = options.scheduler
    self.config = options.config
    self.environment = options.environment
    self.logger = options.logger
    self.state = "stopped"
    self.entries = {}
    self.folder = nil
    self.visibleCount = 0
    self.approvedCount = 0
    self._style = nil
    self._taskName = "target.visuals"
    return self
end

local function localRoot(): BasePart?
    local character = Players.LocalPlayer and Players.LocalPlayer.Character
    if not character then
        return nil
    end
    local root = character:FindFirstChild("HumanoidRootPart")
    return root and root:IsA("BasePart") and root or nil
end

local function approvedModel(instance: Instance): Model?
    if not instance:IsA("Model")
        or not instance:IsDescendantOf(workspace)
        or instance:GetAttribute(Protocol.ATTRIBUTES.Fixture) ~= true
        or instance:GetAttribute(Protocol.ATTRIBUTES.Approved) ~= true
        or Util.isPlayerCharacter(instance)
    then
        return nil
    end
    return instance
end

function TargetVisualizer:_destroyEntry(entry: table)
    if entry.billboard then
        entry.billboard:Destroy()
    end
    if entry.highlight then
        entry.highlight:Destroy()
    end
end

function TargetVisualizer:_ensureFolder()
    local playerGui = Players.LocalPlayer and Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
    if not playerGui then
        return nil
    end
    local existing = playerGui:FindFirstChild(GUI_NAME)
    if existing then
        existing:Destroy()
    end
    local folder = Instance.new("ScreenGui")
    folder.Name = GUI_NAME
    folder.ResetOnSpawn = false
    folder.IgnoreGuiInset = true
    folder.DisplayOrder = 50
    folder.Parent = playerGui
    self.folder = folder
    return folder
end

function TargetVisualizer:_createEntry(model: Model, root: BasePart): table
    local billboard = Instance.new("BillboardGui")
    billboard.Name = "AgamtrashApprovedTarget"
    billboard.Adornee = root
    billboard.AlwaysOnTop = true
    billboard.MaxDistance = self.config:getValue("Combat.VisualRange")
    billboard.Size = UDim2.fromOffset(230, 58)
    billboard.StudsOffsetWorldSpace = Vector3.new(0, 3.1, 0)
    billboard.LightInfluence = 0

    local background = Instance.new("Frame")
    background.Size = UDim2.fromScale(1, 1)
    background.BackgroundColor3 = Color3.fromRGB(15, 21, 29)
    background.BackgroundTransparency = 0.18
    background.BorderSizePixel = 0
    background.Parent = billboard

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 7)
    corner.Parent = background

    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(51, 133, 219)
    stroke.Transparency = 0.2
    stroke.Thickness = 1
    stroke.Parent = background

    local title = Instance.new("TextLabel")
    title.Name = "TargetName"
    title.Size = UDim2.new(1, -16, 0, 24)
    title.Position = UDim2.fromOffset(8, 4)
    title.BackgroundTransparency = 1
    title.Font = Enum.Font.GothamBold
    title.TextSize = 14
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.TextColor3 = Color3.fromRGB(236, 242, 250)
    title.Text = "Approved target"
    title.Parent = background

    local detail = Instance.new("TextLabel")
    detail.Name = "TargetDetail"
    detail.Size = UDim2.new(1, -16, 0, 20)
    detail.Position = UDim2.fromOffset(8, 29)
    detail.BackgroundTransparency = 1
    detail.Font = Enum.Font.Gotham
    detail.TextSize = 12
    detail.TextXAlignment = Enum.TextXAlignment.Left
    detail.TextColor3 = Color3.fromRGB(126, 190, 255)
    detail.Text = ""
    detail.Parent = background

    billboard.Parent = self.folder

    local entry = {
        billboard = billboard,
        title = title,
        detail = detail,
        highlight = nil,
    }
    if self.config:getValue("Combat.Style") == "Billboard + Highlight" then
        local highlight = Instance.new("Highlight")
        highlight.Name = "AgamtrashApprovedTargetHighlight"
        highlight.Adornee = model
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.FillColor = Color3.fromRGB(40, 129, 225)
        highlight.FillTransparency = 0.8
        highlight.OutlineColor = Color3.fromRGB(97, 181, 255)
        highlight.OutlineTransparency = 0.15
        highlight.Parent = model
        entry.highlight = highlight
    end
    return entry
end

function TargetVisualizer:_updateEntry(entry: table, model: Model, distance: number)
    local displayName = Validation.cleanText(model:GetAttribute(Protocol.ATTRIBUTES.DisplayName), 60) or model.Name
    if self.config:getValue("Combat.ShowName") == false then
        entry.title.Text = "Approved target"
    else
        entry.title.Text = displayName
    end

    local pieces = {}
    if self.config:getValue("Combat.ShowDistance") then
        table.insert(pieces, Util.formatDistance(distance))
    end
    local humanoid = model:FindFirstChildOfClass("Humanoid")
    if self.config:getValue("Combat.ShowHealth") and humanoid then
        table.insert(pieces, string.format("HP %d/%d", math.max(0, math.floor(humanoid.Health)), math.floor(humanoid.MaxHealth)))
    end
    if #pieces == 0 then
        table.insert(pieces, "approved test target")
    end
    entry.detail.Text = table.concat(pieces, "  ·  ")
end

function TargetVisualizer:refresh()
    if self.state ~= "running" then
        return
    end
    local root = localRoot()
    if not root then
        for _, entry in pairs(self.entries) do
            self:_destroyEntry(entry)
        end
        self.entries = {}
        self.visibleCount = 0
        return
    end

    local style = self.config:getValue("Combat.Style")
    if style ~= self._style then
        for _, entry in pairs(self.entries) do
            self:_destroyEntry(entry)
        end
        self.entries = {}
        self._style = style
    end

    local range = self.config:getValue("Combat.VisualRange")
    local seen = {}
    local approved = 0
    local visible = 0

    for _, instance in ipairs(CollectionService:GetTagged(Protocol.TAGS.CombatTarget)) do
        local model = approvedModel(instance)
        if model then
            approved += 1
            local targetRoot = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart", true)
            if targetRoot then
                local distance = (root.Position - model:GetPivot().Position).Magnitude
                if distance <= range then
                    visible += 1
                    seen[model] = true
                    local entry = self.entries[model]
                    if not entry then
                        entry = self:_createEntry(model, targetRoot)
                        self.entries[model] = entry
                    end
                    entry.billboard.Adornee = targetRoot
                    entry.billboard.MaxDistance = range
                    self:_updateEntry(entry, model, distance)
                end
            end
        end
    end

    for model, entry in pairs(self.entries) do
        if not seen[model] or not model.Parent or not model:IsDescendantOf(workspace) then
            self:_destroyEntry(entry)
            self.entries[model] = nil
        end
    end
    self.visibleCount = visible
    self.approvedCount = approved
end

function TargetVisualizer:start(): (boolean, string?)
    if self.state == "running" then
        return true, nil
    end
    if not Players.LocalPlayer then
        return false, "CHARACTER_UNAVAILABLE"
    end
    local reason = self.environment:featureReason("TargetVisualization", true)
    if reason then
        return false, reason
    end
    if not self:_ensureFolder() then
        return false, "INVALID_ENVIRONMENT"
    end
    self.state = "running"
    self._style = nil
    self.entries = {}
    self.scheduler:every(self._taskName, 0.5, function()
        local ok, err = pcall(function()
            self:refresh()
        end)
        if not ok then
            self.logger:warn("Target visualization refresh failed: " .. Validation.truncate(err, 160))
        end
    end, true)
    return true, nil
end

function TargetVisualizer:stop()
    self.state = "stopped"
    self.scheduler:cancel(self._taskName)
    for _, entry in pairs(self.entries) do
        self:_destroyEntry(entry)
    end
    self.entries = {}
    self.visibleCount = 0
    self.approvedCount = 0
    if self.folder then
        self.folder:Destroy()
        self.folder = nil
    end
end

function TargetVisualizer:rebuild()
    if self.state ~= "running" then
        return
    end
    for _, entry in pairs(self.entries) do
        self:_destroyEntry(entry)
    end
    self.entries = {}
    self._style = nil
    self:refresh()
end

function TargetVisualizer:isRunning(): boolean
    return self.state == "running"
end

function TargetVisualizer:getStatusText(): string
    if self.state ~= "running" then
        return "stopped"
    end
    return string.format("running · %d shown / %d approved", self.visibleCount, self.approvedCount)
end

return TargetVisualizer
end

__modules["Client.UIController"] = function()
--!nonstrict
-- Rayfield presentation layer. Every control is a thin, defensive adapter over
-- Runtime; this module never invokes remotes, changes collision or writes game
-- currency. Rayfield callbacks are guarded because :Set() also fires callbacks.
--
-- Labels and diagnostics are bounded and sanitized before they reach Rayfield.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local UserInputService = game:GetService("UserInputService")

local Protocol = __require("Shared.Protocol")
local Theme = __require("Shared.Theme")
local Validation = __require("Shared.Validation")

local UIController = {}
UIController.__index = UIController

local WINDOW_NAME = "agamtrash.hub"
local WINDOW_SUBTITLE = "Fight in a Supermarket"
local STATUS_TASK = "ui.status.refresh"
local TOGGLE_KEYS = {
    [Enum.KeyCode.Insert] = true,
    [Enum.KeyCode.RightControl] = true,
}
local UNLOAD_KEY = Enum.KeyCode.Delete

local function text(value: any, maximum: number?): string
    return Validation.cleanText(tostring(value or ""), maximum or 240) or ""
end

local function dropdownValue(option: any): string?
    if type(option) == "string" then
        return option
    end
    if type(option) == "table" then
        local first = option[1]
        if type(first) == "string" then
            return first
        end
    end
    return nil
end

local function copyList(list: { string }): { string }
    local copy = {}
    for index, value in ipairs(list or {}) do
        copy[index] = value
    end
    return copy
end

function UIController.new(runtime: any, library: any, options: any?): (any?, string?)
    if type(runtime) ~= "table" or type(library) ~= "table" then
        return nil, "Runtime or Rayfield library was not provided."
    end

    local self = setmetatable({}, UIController)
    self._runtime = runtime
    self._library = library
    self._config = runtime:getConfig()
    self._settings = options or {}
    self._window = nil
    self._destroyed = false
    self._suppress = 0
    self._tabs = {}
    self._status = {}
    self._featureToggles = {}
    self._configToggles = {}
    self._configSliders = {}
    self._configDropdowns = {}
    self._itemCategory = nil
    self._inputConnection = nil
    self._visibilityBusy = false

    local ok, err = pcall(function()
        self:_createWindow()
        self:_buildMoney(self._tabs.Money)
        self:_buildCombat(self._tabs.Combat)
        self:_buildMisc(self._tabs.Misc)
        self:_buildSettings(self._tabs.Settings)
        self:_bindWindowHotkeys()
    end)
    if not ok then
        self._destroyed = true
        return nil, Validation.truncate(err, 240)
    end

    local scheduled = runtime:addTask(STATUS_TASK, 1.5, function()
        self:refreshStatus()
    end, true)
    if not scheduled then
        runtime:cancelTask(STATUS_TASK)
        runtime:addTask(STATUS_TASK, 1.5, function()
            self:refreshStatus()
        end, true)
    end
    self:refreshStatus()
    return self, nil
end

function UIController:_createWindow()
    local initialTheme = self._config:getValue("Settings.Theme")
    local window = self._library:CreateWindow({
        Name = WINDOW_NAME,
        LoadingTitle = WINDOW_NAME,
        LoadingSubtitle = WINDOW_SUBTITLE,
        Theme = Theme.resolve(initialTheme),
        Icon = 0,
        DisableRayfieldPrompts = true,
        ConfigurationSaving = {
            Enabled = false,
        },
    })
    if type(window) ~= "table" then
        error("Rayfield did not return a window.")
    end
    if type(window.CreateTab) ~= "function" then
        error("Rayfield window is missing CreateTab.")
    end
    if type(window.ModifyTheme) ~= "function" then
        error("Rayfield window is missing ModifyTheme.")
    end
    self._window = window

    self._tabs.Money = window:CreateTab("Money")
    self._tabs.Combat = window:CreateTab("Combat")
    self._tabs.Misc = window:CreateTab("Misc")
    self._tabs.Settings = window:CreateTab("Settings")
    for _, name in ipairs({ "Money", "Combat", "Misc", "Settings" }) do
        if type(self._tabs[name]) ~= "table" then
            error("Rayfield could not create the " .. name .. " tab.")
        end
    end
end

function UIController:_windowVisible(): boolean
    local ok, value = pcall(self._library.IsVisible, self._library)
    if ok and type(value) == "boolean" then
        return value
    end
    return true
end

function UIController:_setWindowVisible(visible: boolean)
    if self._destroyed or self._visibilityBusy then
        return
    end
    self._visibilityBusy = true
    task.spawn(function()
        local ok, err = pcall(function()
            if self._destroyed then
                return
            end
            self._library:SetVisibility(visible == true)
        end)
        if not ok then
            self:_internalError(err)
        end
        -- Rayfield animates Hide/Unhide for 0.5s and silently ignores a second
        -- call while its own debounce is active. Keep our controls locked for
        -- the same window so a double click cannot leave them desynchronized.
        task.wait(0.6)
        self._visibilityBusy = false
    end)
end

function UIController:_toggleWindow()
    if self._destroyed or self._visibilityBusy then
        return
    end
    self:_setWindowVisible(not self:_windowVisible())
end

function UIController:_bindWindowHotkeys()
    local ok, connection = pcall(function()
        return UserInputService.InputBegan:Connect(function(input, processed)
            if self._destroyed or processed then
                return
            end
            if TOGGLE_KEYS[input.KeyCode] then
                self:_toggleWindow()
            elseif input.KeyCode == UNLOAD_KEY then
                self:_requestUnload()
            end
        end)
    end)
    if ok then
        self._inputConnection = connection
    end
end

function UIController:_guarded(callback: (...any) -> ())
    return function(...)
        if self._destroyed or self._suppress > 0 then
            return
        end
        local ok, err = pcall(callback, ...)
        if not ok then
            self:_internalError(err)
        end
    end
end

function UIController:_internalError(err: any)
    local message = Validation.truncate(err, 180)
    self._runtime:getDiagnosticsLogger():error("UI callback failed: " .. message)
    self:notify("Interface Error", "An interface action failed. See the diagnostic log.")
end

function UIController:_setControl(control: any, value: any)
    if not control or type(control.Set) ~= "function" then
        return false
    end
    self._suppress += 1
    local ok = pcall(control.Set, control, value)
    self._suppress -= 1
    return ok
end

function UIController:_paragraph(tab: any, key: string, title: string, content: string, store: boolean?)
    local paragraph = tab:CreateParagraph({
        Title = title,
        Content = content,
    })
    if store ~= false and key then
        self._status[key] = paragraph
    end
    return paragraph
end

function UIController:_setStatus(key: string, title: string, content: string)
    local paragraph = self._status[key]
    if paragraph then
        pcall(paragraph.Set, paragraph, {
            Title = text(title, 80),
            Content = text(content, 1600),
        })
    end
end

function UIController:_notify(title: string, content: string)
    local safeTitle = text(title, 60)
    local safeContent = text(content, 300)
    if safeTitle == "" then
        safeTitle = "agamtrash.hub"
    end
    if safeContent == "" then
        safeContent = "No details available."
    end
    pcall(self._library.Notify, self._library, {
        Title = safeTitle,
        Content = safeContent,
        Duration = 6,
    })
end

function UIController:notify(title: string, content: string)
    if self._destroyed then
        return
    end
    self:_notify(title, content)
end

function UIController:_bindConfigToggle(tab: any, path: string, name: string)
    local control
    control = tab:CreateToggle({
        Name = name,
        CurrentValue = self._config:getValue(path) == true,
        Callback = self:_guarded(function(state)
            local ok, reason = self._runtime:setConfig(path, state == true)
            if not ok then
                self:_setControl(control, self._config:getValue(path) == true)
                self:_notify("Configuration", reason or Protocol.message("INVALID_CONFIG"))
            end
        end),
    })
    self._configToggles[path] = control
    return control
end

function UIController:_bindConfigSlider(tab: any, path: string, name: string, range: { number }, increment: number, suffix: string)
    local control
    control = tab:CreateSlider({
        Name = name,
        Range = range,
        Increment = increment,
        Suffix = suffix,
        CurrentValue = self._config:getValue(path),
        Callback = self:_guarded(function(value)
            local rounded = math.floor(value / increment + 0.5) * increment
            if increment < 1 then
                rounded = math.floor(rounded * 100 + 0.5) / 100
            end
            rounded = math.clamp(rounded, range[1], range[2])
            local ok, reason = self._runtime:setConfig(path, rounded)
            if not ok then
                self:_setControl(control, self._config:getValue(path))
                self:_notify("Configuration", reason or Protocol.message("INVALID_CONFIG"))
            elseif rounded ~= value then
                self:_setControl(control, rounded)
            end
        end),
    })
    self._configSliders[path] = { control = control, increment = increment }
    return control
end

function UIController:_bindConfigDropdown(tab: any, path: string, name: string, options: { string })
    local control
    control = tab:CreateDropdown({
        Name = name,
        Options = copyList(options),
        CurrentOption = { self._config:getValue(path) },
        Callback = self:_guarded(function(option)
            local choice = dropdownValue(option)
            if not choice then
                self:_setControl(control, { self._config:getValue(path) })
                return
            end
            local ok, reason = self._runtime:setConfig(path, choice)
            if not ok then
                self:_setControl(control, { self._config:getValue(path) })
                self:_notify("Configuration", reason or Protocol.message("INVALID_CONFIG"))
            elseif path == "Settings.Theme" then
                self:_applyTheme(choice)
            end
        end),
    })
    self._configDropdowns[path] = control
    return control
end

function UIController:_featureToggle(tab: any, key: string, name: string, initial: boolean, callback: (boolean) -> ())
    local control
    control = tab:CreateToggle({
        Name = name,
        CurrentValue = initial == true,
        Callback = self:_guarded(function(state)
            local ok = callback(state == true)
            if not ok then
                self:_setControl(control, self._runtime:getFeatureStates()[key] == true)
            else
                self:refreshStatus()
            end
        end),
    })
    self._featureToggles[key] = control
    return control
end

function UIController:_button(tab: any, name: string, callback: () -> ())
    return tab:CreateButton({
        Name = name,
        Callback = self:_guarded(callback),
    })
end

function UIController:_buildMoney(tab: any)
    tab:CreateSection("Auto Collect Money")
    self:_paragraph(
        tab,
        "moneyIntro",
        WINDOW_NAME .. " · " .. WINDOW_SUBTITLE,
        "Authorized development sandbox only. Scans server-created test pickups. The server independently validates fixture ownership, distance, availability and the mock ledger."
    )

    self:_featureToggle(tab, "Money", "Auto Collect Money", false, function(enabled)
        return self._runtime:setAutoMoney(enabled)
    end)
    self:_button(tab, "Collect Nearest Now", function()
        self._runtime:collectNearest()
        self:refreshStatus()
    end)
    self:_bindConfigSlider(tab, "Money.Radius", "Collection radius", { 100, 10000 }, 100, "studs")
    self:_bindConfigSlider(tab, "Money.Interval", "Scan interval", { 0.25, 5.0 }, 0.25, "s")
    self:_button(tab, "Refresh Money Diagnostics", function()
        self:refreshStatus()
        self:notify("Money Diagnostics", "The diagnostics panel was refreshed.")
    end)

    self:_paragraph(tab, "moneyStatus", "Money diagnostics", "Waiting for the first status refresh...")
end

function UIController:_buildCombat(tab: any)
    tab:CreateSection("Combat Test Mode")
    self:_paragraph(
        tab,
        "combatIntro",
        "Approved test NPCs only",
        "Combat never accepts player characters or client-supplied target names, positions or damage. Only server-tagged, explicitly approved development dummies are eligible."
    )
    self:_featureToggle(tab, "Combat", "Combat Test Mode", false, function(enabled)
        return self._runtime:setCombat(enabled)
    end)
    self:_button(tab, "Attack Nearest Approved Target", function()
        self._runtime:attackNearest()
        self:refreshStatus()
    end)
    self:_bindConfigSlider(tab, "Combat.Range", "Attack range", { 5, 100 }, 1, "studs")
    self:_bindConfigSlider(tab, "Combat.Interval", "Attack interval", { 0.5, 5.0 }, 0.5, "s")
    self:_paragraph(tab, "combatStatus", "Combat status", "Waiting for the first status refresh...")

    tab:CreateSection("Target Visualization")
    self:_paragraph(
        tab,
        "targetIntro",
        "Approved targets only",
        "Billboards and optional highlights are created only for tagged models with the AgamtrashApproved attribute. Player characters are excluded in every scan."
    )
    self:_featureToggle(tab, "TargetVisualization", "Show Approved Targets", false, function(enabled)
        return self._runtime:setTargetVisualization(enabled)
    end)
    self:_bindConfigSlider(tab, "Combat.VisualRange", "Visual range", { 10, 500 }, 10, "studs")
    self:_bindConfigDropdown(tab, "Combat.Style", "Visual style", { "Billboard", "Billboard + Highlight" })
    self:_bindConfigToggle(tab, "Combat.ShowName", "Show target names")
    self:_bindConfigToggle(tab, "Combat.ShowDistance", "Show distance")
    self:_bindConfigToggle(tab, "Combat.ShowHealth", "Show health")
    self:_paragraph(tab, "targetStatus", "Visualization status", "Waiting for the first status refresh...")
end

function UIController:_buildMisc(tab: any)
    tab:CreateSection("ATM Auto Interaction Test")
    self:_paragraph(
        tab,
        "atmIntro",
        "Reference label: " .. Protocol.COMMAND_LABEL,
        "This hub does not create infinite money. Every request is a server-validated test transaction in the authorized sandbox. Mock credits are bounded by a per-session cap, per-ATM cooldown, idempotency and rate limits."
    )
    self:_featureToggle(tab, "ATM", "ATM Auto Interaction Test", false, function(enabled)
        return self._runtime:setATM(enabled)
    end)
    self:_button(tab, "Interact With Nearest Test ATM", function()
        self._runtime:atmInteractOnce()
        self:refreshStatus()
    end)
    self:_bindConfigSlider(tab, "ATM.Interval", "Request interval", { 0.5, 10.0 }, 0.5, "s")
    self:_bindConfigDropdown(tab, "ATM.Mode", "Mode", { "validate", "mock" })
    self:_paragraph(tab, "atmStatus", "ATM test status", "Waiting for the first status refresh...")

    tab:CreateSection("Item ESP")
    self:_paragraph(
        tab,
        "itemIntro",
        "Actual fixture metadata only",
        "Names and categories come from server-created attributes. The scanner refreshes on a scheduled task and filters only by categories it has actually observed."
    )
    self:_featureToggle(tab, "ItemVisualization", "Item ESP", false, function(enabled)
        return self._runtime:setItemESP(enabled)
    end)
    self:_bindConfigSlider(tab, "Items.VisualRange", "Item visual range", { 50, 1000 }, 10, "studs")
    self._itemCategory = tab:CreateDropdown({
        Name = "Item category",
        Options = copyList(self._runtime:getItemCategories()),
        CurrentOption = { self._runtime:getItemCategory() },
        Callback = self:_guarded(function(option)
            local choice = dropdownValue(option)
            if choice then
                self._runtime:setItemCategory(choice)
                self:refreshStatus()
            end
        end),
    })
    self:_bindConfigDropdown(tab, "Items.Style", "Item visual style", { "Billboard", "Billboard + Highlight" })
    self:_bindConfigToggle(tab, "Items.ShowName", "Show item names")
    self:_bindConfigToggle(tab, "Items.ShowDistance", "Show item distance")
    self:_paragraph(tab, "itemStatus", "Item ESP status", "Waiting for the first status refresh...")

    tab:CreateSection("Noclip Debug")
    self:_paragraph(
        tab,
        "noclipIntro",
        "Server-authoritative debug session",
        "Available only in an authorized development session. The server records and restores original CanCollide and CollisionGroup values on disable, death, character removal or timeout. Live behavior depends on the executor and network ownership."
    )
    self:_featureToggle(tab, "Noclip", "Noclip Debug", false, function(enabled)
        return self._runtime:setNoclip(enabled)
    end)
    self:_paragraph(tab, "noclipStatus", "Noclip status", "Inactive.")
end

function UIController:_buildSettings(tab: any)
    tab:CreateSection("Status")
    self:_paragraph(
        tab,
        "settingsIntro",
        WINDOW_NAME .. " · " .. WINDOW_SUBTITLE,
        "Publication " .. Protocol.VERSION .. " · Rayfield " .. Protocol.RAYFIELD.Release .. " (" .. Protocol.RAYFIELD.InterfaceBuild .. ") · protocol " .. tostring(Protocol.PROTOCOL)
    )
    self:_paragraph(tab, "environmentStatus", "Environment", "Contacting the authorized server component...")
    self:_paragraph(tab, "moduleStatus", "Module status", "Waiting for the first status refresh...")
    self:_button(tab, "Refresh Status", function()
        self:refreshStatus()
    end)

    tab:CreateSection("Appearance")
    self:_bindConfigDropdown(tab, "Settings.Theme", "Theme", { "Agamtrash Charcoal", "DarkBlue", "Default" })

    tab:CreateSection("Diagnostics")
    self:_bindConfigToggle(tab, "Settings.DebugLogging", "Debug logging")
    self:_button(tab, "Run Compatibility Check", function()
        local report = self._runtime:buildCompatibilityReport()
        self:_setStatus("compatibility", "Compatibility report", report)
        self:notify("Compatibility Check", "Report updated on the Settings tab.")
        self:refreshStatus()
    end)
    self:_paragraph(tab, "compatibility", "Compatibility report", "Run the check to collect the current environment and executor details.")
    self:_button(tab, "Clear Diagnostics", function()
        self._runtime:getDiagnosticsLogger():clear()
        self:notify("Diagnostics", "The in-memory diagnostic log was cleared.")
        self:refreshStatus()
    end)

    tab:CreateSection("Session")
    self:_paragraph(
        tab,
        "windowControls",
        "Window controls",
"Insert or RightControl hides or shows the hub. Delete unloads it and cleans up every module. These hotkeys work even when Rayfield's own topbar icons are hard to reach."
    )
    self:_button(tab, "Hide Hub (Insert)", function()
        self:_setWindowVisible(false)
    end)
    self:_paragraph(
        tab,
        "resetNotice",
        "Session-only configuration",
        "Configuration is never written to disk. Reset restores defaults and stops all modules; no feature is auto-started."
    )
    self:_button(tab, "Stop All Modules", function()
        self._runtime:stopAll("manual stop")
        self:refreshStatus()
    end)
    self:_button(tab, "Reset Session Configuration", function()
        self._runtime:resetSession()
        self:refreshStatus()
        self:notify("Configuration", "Session configuration reset to defaults.")
    end)
    self:_button(tab, "Unload Hub and Clean Up", function()
        self:_requestUnload()
    end)
end

function UIController:_requestUnload()
    if self._settings.onUnload then
        local ok, err = pcall(self._settings.onUnload)
        if ok then
            return
        end
        self:_internalError(err)
    end
    self:destroy()
end

function UIController:_applyTheme(name: string)
    local ok, err = pcall(self._window.ModifyTheme, self._window, Theme.resolve(name))
    if not ok then
        self._runtime:getDiagnosticsLogger():warn("Theme change failed: " .. Validation.truncate(err, 160))
        self:notify("Theme", "Rayfield could not apply that theme.")
    end
end

function UIController:_syncFeatureToggles()
    local states = self._runtime:getFeatureStates()
    local mapping = {
        Money = "Money",
        Combat = "Combat",
        TargetVisualization = "TargetVisualization",
        ItemVisualization = "ItemVisualization",
        ATM = "ATM",
    }
    for feature, key in pairs(mapping) do
        local control = self._featureToggles[key]
        local wanted = states[feature] == true
        if control and control.CurrentValue ~= wanted then
            self:_setControl(control, wanted)
        end
    end

    local noclip = self._featureToggles.Noclip
    if noclip then
        local wanted = states.Noclip == true or states.NoclipRequesting == true
        if noclip.CurrentValue ~= wanted then
            self:_setControl(noclip, wanted)
        end
    end
end

function UIController:_syncConfigControls()
    for path, control in pairs(self._configToggles) do
        self:_setControl(control, self._config:getValue(path) == true)
    end
    for path, entry in pairs(self._configSliders) do
        self:_setControl(entry.control, self._config:getValue(path))
    end
    for path, control in pairs(self._configDropdowns) do
        self:_setControl(control, { self._config:getValue(path) })
    end
    self:_applyTheme(self._config:getValue("Settings.Theme"))
end

function UIController:refreshStatus()
    if self._destroyed then
        return
    end
    local ok, err = pcall(function()
        local snapshot = self._runtime:getStatusSnapshot()
        self:_syncFeatureToggles()

        self:_setStatus("moneyStatus", "Money diagnostics", snapshot.money)
        self:_setStatus("combatStatus", "Combat status", snapshot.combat .. "\n" .. snapshot.combatDetail)
        self:_setStatus("targetStatus", "Visualization status", snapshot.targets)
        self:_setStatus("atmStatus", "ATM test status", snapshot.atm .. "\n" .. snapshot.atmDetail)
        self:_setStatus("itemStatus", "Item ESP status", snapshot.items)
        self:_setStatus("noclipStatus", "Noclip status", snapshot.noclip)
        self:_setStatus("environmentStatus", "Environment", snapshot.environment .. "\n" .. snapshot.environmentDetail)
        self:_setStatus("moduleStatus", "Module status", snapshot.modules)
    end)
    if not ok then
        self._runtime:getDiagnosticsLogger():warn("Status refresh failed: " .. Validation.truncate(err, 160))
    end
end

function UIController:onAutoStopped(feature: string, code: string)
    if self._destroyed then
        return
    end
    local control = self._featureToggles[feature]
    if control then
        self:_setControl(control, false)
    end
    self:refreshStatus()
end

function UIController:onConfigReset()
    if self._destroyed then
        return
    end
    self:_syncConfigControls()
    if self._itemCategory then
        self:_setControl(self._itemCategory, { self._runtime:getItemCategory() })
    end
    self:refreshStatus()
end

function UIController:onNoclipState(status: table)
    if self._destroyed then
        return
    end
    local control = self._featureToggles.Noclip
    if control then
        local wanted = status ~= nil and (status.active == true or status.requesting == true)
        if control.CurrentValue ~= wanted then
            self:_setControl(control, wanted)
        end
    end
    self:refreshStatus()
end

function UIController:onItemCategories(categories: { string }, filter: string?)
    if self._destroyed or not self._itemCategory then
        return
    end
    local options = copyList(categories)
    if #options == 0 then
        options = { "All" }
    end
    pcall(self._itemCategory.Refresh, self._itemCategory, options)
    local selected = filter or "All"
    if selected == "" or not table.find(options, selected) then
        selected = "All"
    end
    self:_setControl(self._itemCategory, { selected })
end

function UIController:destroy()
    if self._destroyed then
        return
    end
    self._destroyed = true
    if self._inputConnection then
        pcall(function()
            self._inputConnection:Disconnect()
        end)
        self._inputConnection = nil
    end
    pcall(self._runtime.cancelTask, self._runtime, STATUS_TASK)
    -- Destroy the window through Rayfield's own lifecycle. Boot also calls
    -- library.Destroy as a final guard; Rayfield's Destroy is pcall-protected.
    if self._window then
        pcall(self._library.Destroy, self._library)
        self._window = nil
    end
end

return UIController
end

local __bootOk, __bootError = pcall(function()
    local Boot = __require("Client.Boot")
    local started, success, detail = pcall(Boot.start)
    if not started then
        warn("[agamtrash.hub] Boot failed: " .. tostring(success))
    elseif not success then
        warn("[agamtrash.hub] Boot stopped: " .. tostring(detail))
    end
end)
if not __bootOk then
    warn("[agamtrash.hub] Bundle failed: " .. tostring(__bootError))
end
